window.STORYSPROUT_BOOKS[3]={"number":3,"title":"Super Minds 3","edition":"Cambridge University Press · 2012","teacherAvailable":false,"sourceNote":"依据所提供的 Super Minds 3 Student’s Book（2012）编写。页码为书内印刷页；短文为教学改写或明确标注的新编练习，不代替全书原文。未提供第三册教师用书及原配音频。","bookSummary":"跟 Ben、Lucy 和 Buster 寻找七个字母：从学校、野餐和城镇，到海底、洞穴与世界建筑，读懂故事、比较信息，并用过去时和将来计划讲述自己的经历。","storyGuide":"古书里的密码带出七个字母 I、F、R、S、E、N、D。Horax 和 Zelda 一路争夺古书；最后，真正打开宝藏的是 FRIENDS（朋友）。","pageMin":2,"pageMax":127,"pageBase":"books/3/pages","grammarAppendix":true,"units":[{"id":0,"title":"Meet The Explorers","zh":"认识探险家","icon":"🧭","goal":"认识 Ben、Lucy 和 Buster；说出自己的本领，并讲清古书怎样失而复得。","start":4,"end":9,"teacher":"未提供教师用书；依据学生用书编写","grammarPage":118,"vocab":[{"word":"upstairs","zh":"在楼上","example":"The bedroom is upstairs."},{"word":"downstairs","zh":"在楼下","example":"The kitchen is downstairs."},{"word":"cellar","zh":"地窖","example":"The old box is in the cellar."},{"word":"twenty-one","zh":"二十一","example":"My card has twenty-one stars."},{"word":"fifty","zh":"五十","example":"I can count to fifty."},{"word":"one hundred","zh":"一百","example":"There are one hundred pages."},{"word":"uncle","zh":"叔叔；舅舅等","example":"My uncle has a blue bike."},{"word":"cousin","zh":"堂兄弟姐妹；表兄弟姐妹","example":"My cousin likes puzzles."}],"grammar":[{"title":"good at + 动词 -ing","rule":"be good at 表示擅长；at 后接名词或动词 -ing，否定把 not 放在 be 后。","examples":[{"en":"I am good at riding bikes.","zh":"我擅长骑自行车。"},{"en":"She is not good at singing.","zh":"她不擅长唱歌。"}],"questions":[{"prompt":"I am good at ___ puzzles.","options":["do","doing","does"],"answer":1,"why":"at 后的动作要用 -ing：doing。","kind":"grammar","id":"u0-g0-q0"},{"prompt":"哪句表示“他不擅长游泳”？","options":["He is good at swimming.","He not good at swim.","He is not good at swimming."],"answer":2,"why":"is not 表示否定；at 后用 swimming。","kind":"grammar","id":"u0-g0-q1"}]},{"title":"用 ’s 表示所属关系","rule":"人名后加 ’s，可以表示“某人的”。先找人物，再看后面的亲属或物品。","examples":[{"en":"Ben is Penny’s brother.","zh":"Ben 是 Penny 的哥哥／弟弟。"},{"en":"Lucy’s book is old.","zh":"Lucy 的书很旧。"}],"questions":[{"prompt":"Penny is Ben’s sister. 谁是谁的姐姐／妹妹？","options":["Penny 是 Ben 的姐姐／妹妹。","Ben 是 Penny 的姐姐／妹妹。","Penny 是 Ben 的妈妈。"],"answer":0,"why":"Ben’s 修饰 sister，意思是“Ben 的姐妹”。","kind":"grammar","id":"u0-g1-q0"},{"prompt":"“Lucy 的狗”应写作：","options":["Lucy dog","Lucys dog","Lucy’s dog"],"answer":2,"why":"单个人名的所属关系可用名字 + ’s。","kind":"grammar","id":"u0-g1-q1"}]}],"phonics":{"title":"短元音：听清中间的音","note":"把短音读清，不在单词末尾额外加一个汉语“呃”。以下练习词依据第 9 页短元音目标新编。","pairs":[{"a":"cat","b":"cap"},{"a":"pet","b":"pen"},{"a":"cup","b":"sun"}],"page":9,"questions":[{"prompt":"pet 和哪一个词中间的元音相同？","options":["pit","pen","pot"],"answer":1,"why":"pet 和 pen 的中间都是 /e/。","kind":"phonics","id":"u0-ph-q0"}]},"song":{"title":"The Explorers","page":6,"task":["打开原书歌谣页，圈出本单元已经会读的词。","用页面的电脑语音练读短句；原版歌曲需另备配套音频。","选一个句型换成自己的信息，说给家人听。"]},"story":{"title":"The old book · 古书失而复得","pages":[8,9],"kind":"依据课文的教学改写","summary":"两位朋友找到藏着宝藏秘密的古书，却被 Horax 和 Zelda 抢走。Buster 帮他们脱困，三位伙伴合作取回古书。","sentences":[{"en":"Ben and Lucy find a secret door in the castle.","zh":"Ben 和 Lucy 在城堡里发现一扇暗门。","note":"secret door：暗门；先交代地点和发现。","id":"u0-story-s0"},{"en":"Behind the door, they find an old book.","zh":"在门后，他们找到一本古书。","note":"behind：在……后面。","id":"u0-story-s1"},{"en":"Horax and Zelda want the book and its treasure.","zh":"Horax 和 Zelda 想要这本书以及它指向的宝藏。","note":"want 后面接想得到的东西。","id":"u0-story-s2"},{"en":"They take the book and tie the children up.","zh":"他们抢走书，并把孩子们绑起来。","note":"tie ... up：把……绑住。","id":"u0-story-s3"},{"en":"Buster helps Ben and Lucy get free.","zh":"Buster 帮助 Ben 和 Lucy 脱身。","note":"get free：获得自由、脱困。","id":"u0-story-s4"},{"en":"Lucy makes a plan to get the book back.","zh":"Lucy 想出一个取回古书的计划。","note":"get ... back：取回……。","id":"u0-story-s5"},{"en":"Buster stops the two thieves while the children escape with the book.","zh":"Buster 拦住两个坏人，孩子们带着书逃走。","note":"while 连接同时发生的两件事。","id":"u0-story-s6"},{"en":"The friends succeed by helping each other.","zh":"朋友们互相帮助，取得了成功。","note":"用一句话说明故事的道理。","id":"u0-story-s7"}],"questions":[{"prompt":"故事的主要问题是什么？","options":["古书没有任何字。","Horax 和 Zelda 抢走了古书。","Buster 不愿意出门。"],"answer":1,"why":"两人先发现古书，随后古书被抢，故事围绕取回它展开。","kind":"meaning","id":"u0-story-q0"},{"prompt":"Buster 起了什么作用？","options":["帮助孩子们脱困并取回古书。","把古书卖掉。","替坏人看守孩子们。"],"answer":0,"why":"Buster 是帮助伙伴的关键角色，不是坏人的帮手。","kind":"meaning","id":"u0-story-q1"}]},"reading":{"title":"Three friends, one adventure · 三位伙伴","pages":[4,5,6,7],"kind":"依据课文的教学改写","summary":"认识人物、任务和本领。把“谁—做什么—为什么”连起来，就能讲明故事的开头。","sentences":[{"en":"Ben and Lucy are two explorers.","zh":"Ben 和 Lucy 是两位探险家。","note":"explorers：探险家。","id":"u0-reading-s0"},{"en":"Their dog is called Buster.","zh":"他们的狗叫 Buster。","note":"is called：名叫。","id":"u0-reading-s1"},{"en":"They find lost treasure and give it to museums.","zh":"他们寻找遗失的宝藏，并把它交给博物馆。","note":"give ... to ...：把……给……。","id":"u0-reading-s2"},{"en":"Today they are looking for an old book in a castle.","zh":"今天，他们在一座城堡里寻找古书。","note":"are looking for：正在寻找。","id":"u0-reading-s3"},{"en":"The book has a secret about some treasure.","zh":"这本书藏着有关宝藏的秘密。","note":"解释为什么找书。","id":"u0-reading-s4"},{"en":"Lucy is good at doing puzzles and reading clues.","zh":"Lucy 擅长解谜和读线索。","note":"clue：线索。","id":"u0-reading-s5"},{"en":"Ben is good at riding bikes and swimming.","zh":"Ben 擅长骑自行车和游泳。","note":"两个 -ing 动作并列。","id":"u0-reading-s6"},{"en":"Different skills help the friends work together.","zh":"不同的本领帮助朋友们合作。","note":"这是对人物分工的概括。","id":"u0-reading-s7"}],"questions":[{"prompt":"他们找到宝藏后通常会怎么做？","options":["藏在自己的卧室。","交给博物馆。","扔回海里。"],"answer":1,"why":"开头明确说他们把宝藏交给 museums。","kind":"meaning","id":"u0-reading-q0"},{"prompt":"他们为什么寻找古书？","options":["因为书里有关于宝藏的秘密。","因为他们要买新书包。","因为这本书能教做饭。"],"answer":0,"why":"寻找古书是为了得到宝藏线索。","kind":"meaning","id":"u0-reading-q1"}]},"world":{"title":"My explorer notebook · 我的线索本","pages":[4,5,7],"kind":"依据单元目标新编","summary":"本篇依据入门单元新编：用线索本练习区分人物、地点、本领和所属关系。","sentences":[{"en":"I make an explorer notebook.","zh":"我做一本探险笔记。","note":"新编学习情境。","id":"u0-world-s0"},{"en":"On the first page, I write the names of the team.","zh":"第一页，我写下小队成员的名字。","note":"names：姓名。","id":"u0-world-s1"},{"en":"On the next page, I draw a castle.","zh":"下一页，我画一座城堡。","note":"next：下一个。","id":"u0-world-s2"},{"en":"I put the cellar below the other rooms.","zh":"我把地窖画在其他房间下面。","note":"below：在下方。","id":"u0-world-s3"},{"en":"I write, “I am good at drawing maps.”","zh":"我写道：“我擅长画地图。”","note":"good at + drawing。","id":"u0-world-s4"},{"en":"My cousin is good at reading clues.","zh":"我的表亲擅长读线索。","note":"介绍另一位成员的本领。","id":"u0-world-s5"},{"en":"This is my cousin’s pencil, and that is my notebook.","zh":"这是我表亲的铅笔，那是我的笔记本。","note":"’s 表示所属。","id":"u0-world-s6"},{"en":"Our different skills can help the whole team.","zh":"我们不同的本领可以帮助整个小队。","note":"whole team：整个团队。","id":"u0-world-s7"}],"questions":[{"prompt":"笔记中的地窖画在哪里？","options":["其他房间上面。","其他房间下面。","城堡外的天空中。"],"answer":1,"why":"below the other rooms 表示其他房间下方。","kind":"meaning","id":"u0-world-q0"},{"prompt":"这段新编短文强调哪种做法？","options":["只记录自己擅长的事，忽略伙伴。","不记录任何线索。","把每个人的不同本领用在合作中。"],"answer":2,"why":"最后一句指出不同技能可以帮助整个小队。","kind":"meaning","id":"u0-world-q1"}]},"create":{"title":"画一张探险家名片","pages":[5,7,8,9],"tasks":["画出自己和一位伙伴，并各写一项本领。","用 good at 说一句肯定句、一句否定句。","按“找到书—书被抢—合作取回”口头复述。"],"frame":"My name is ...\nI am good at ...\nI am not good at ...\nMy friend is good at ...\nFirst ... Then ... Finally ...","model":"Ben and Lucy find an old book. Horax and Zelda take it. Buster helps the children get free. The friends work together and get the book back.","success":"能说清主要人物、遇到的问题和解决办法；本领句使用 at + -ing。","teacher":"依据所列学生用书活动设计的家庭练习；示范与评价标准为新编，非教师用书标准答案。"},"extra":[],"questions":[{"prompt":"I am good at ___ puzzles.","options":["do","doing","does"],"answer":1,"why":"at 后的动作要用 -ing：doing。","kind":"grammar","id":"u0-g0-q0"},{"prompt":"哪句表示“他不擅长游泳”？","options":["He is good at swimming.","He not good at swim.","He is not good at swimming."],"answer":2,"why":"is not 表示否定；at 后用 swimming。","kind":"grammar","id":"u0-g0-q1"},{"prompt":"Penny is Ben’s sister. 谁是谁的姐姐／妹妹？","options":["Penny 是 Ben 的姐姐／妹妹。","Ben 是 Penny 的姐姐／妹妹。","Penny 是 Ben 的妈妈。"],"answer":0,"why":"Ben’s 修饰 sister，意思是“Ben 的姐妹”。","kind":"grammar","id":"u0-g1-q0"},{"prompt":"“Lucy 的狗”应写作：","options":["Lucy dog","Lucys dog","Lucy’s dog"],"answer":2,"why":"单个人名的所属关系可用名字 + ’s。","kind":"grammar","id":"u0-g1-q1"},{"prompt":"故事的主要问题是什么？","options":["古书没有任何字。","Horax 和 Zelda 抢走了古书。","Buster 不愿意出门。"],"answer":1,"why":"两人先发现古书，随后古书被抢，故事围绕取回它展开。","kind":"meaning","id":"u0-story-q0"},{"prompt":"Buster 起了什么作用？","options":["帮助孩子们脱困并取回古书。","把古书卖掉。","替坏人看守孩子们。"],"answer":0,"why":"Buster 是帮助伙伴的关键角色，不是坏人的帮手。","kind":"meaning","id":"u0-story-q1"},{"prompt":"他们找到宝藏后通常会怎么做？","options":["藏在自己的卧室。","交给博物馆。","扔回海里。"],"answer":1,"why":"开头明确说他们把宝藏交给 museums。","kind":"meaning","id":"u0-reading-q0"},{"prompt":"他们为什么寻找古书？","options":["因为书里有关于宝藏的秘密。","因为他们要买新书包。","因为这本书能教做饭。"],"answer":0,"why":"寻找古书是为了得到宝藏线索。","kind":"meaning","id":"u0-reading-q1"},{"prompt":"笔记中的地窖画在哪里？","options":["其他房间上面。","其他房间下面。","城堡外的天空中。"],"answer":1,"why":"below the other rooms 表示其他房间下方。","kind":"meaning","id":"u0-world-q0"},{"prompt":"这段新编短文强调哪种做法？","options":["只记录自己擅长的事，忽略伙伴。","不记录任何线索。","把每个人的不同本领用在合作中。"],"answer":2,"why":"最后一句指出不同技能可以帮助整个小队。","kind":"meaning","id":"u0-world-q1"},{"prompt":"pet 和哪一个词中间的元音相同？","options":["pit","pen","pot"],"answer":1,"why":"pet 和 pen 的中间都是 /e/。","kind":"phonics","id":"u0-ph-q0"}]},{"id":1,"title":"Our school","zh":"我们的学校","icon":"🏫","goal":"聊喜欢的学科和必须遵守的规则；理解 Johnny 的想象力怎样成为优势。","start":10,"end":21,"teacher":"未提供教师用书；依据学生用书编写","grammarPage":119,"vocab":[{"word":"English","zh":"英语","example":"We read a story in English."},{"word":"Geography","zh":"地理","example":"I like learning about places in Geography."},{"word":"Music","zh":"音乐","example":"We sing in Music."},{"word":"I.T.","zh":"信息技术","example":"I use a computer in I.T."},{"word":"History","zh":"历史","example":"History tells us about the past."},{"word":"Maths","zh":"数学","example":"I solve a number puzzle in Maths."},{"word":"Science","zh":"科学","example":"We learn about plants in Science."},{"word":"Art","zh":"美术","example":"I draw a dragon in Art."},{"word":"P.E.","zh":"体育","example":"We play basketball in P.E."}],"grammar":[{"title":"like / love / don’t like + -ing","rule":"说喜欢做什么时，在 like 或 love 后使用动词 -ing。he/she 的否定用 doesn’t like。","examples":[{"en":"I like listening to stories.","zh":"我喜欢听故事。"},{"en":"He doesn’t like singing.","zh":"他不喜欢唱歌。"}],"questions":[{"prompt":"Lucy loves ___ about animals.","options":["learn","learning","learns"],"answer":1,"why":"love 后表示动作使用 learning。","kind":"grammar","id":"u1-g0-q0"},{"prompt":"He ___ like doing Maths puzzles.","options":["don’t","isn’t","doesn’t"],"answer":2,"why":"he 是第三人称单数，否定用 doesn’t like。","kind":"grammar","id":"u1-g0-q1"}]},{"title":"have to / has to：必须做","rule":"have to 后接动词原形；he/she 用 has to。用它说明规则和必须完成的事。","examples":[{"en":"We have to listen carefully.","zh":"我们必须认真听。"},{"en":"She has to arrive before nine.","zh":"她必须九点前到达。"}],"questions":[{"prompt":"She ___ wear school uniform.","options":["have to","has to","has"],"answer":1,"why":"she 后使用 has to + wear。","kind":"grammar","id":"u1-g1-q0"},{"prompt":"We have to ___ a book every week.","options":["reading","reads","read"],"answer":2,"why":"to 后面接动词原形 read。","kind":"grammar","id":"u1-g1-q1"}]}],"phonics":{"title":"字母名称也有发音规律","note":"第 15 页练习字母名。B、C、D、E 等字母名含长音 /iː/；A、J、K 的字母名含 /eɪ/。","pairs":[{"a":"B","b":"E"},{"a":"C","b":"D"},{"a":"J","b":"K"}],"page":15,"questions":[{"prompt":"哪个字母的名称和 J 一样含 /eɪ/？","options":["K","I","O"],"answer":0,"why":"J /dʒeɪ/ 和 K /keɪ/ 都有 /eɪ/。","kind":"phonics","id":"u1-ph-q0"}]},"song":{"title":"Let me tell you a secret","page":12,"task":["打开原书歌谣页，圈出本单元已经会读的词。","用页面的电脑语音练读短句；原版歌曲需另备配套音频。","选一个句型换成自己的信息，说给家人听。"]},"story":{"title":"Getting help · 破解密码","pages":[14,15],"kind":"依据课文的教学改写","summary":"Ben 和 Lucy 请 Mr Williams 帮忙读密码，但没有把书留给他。后来他们自己找到解码线索，坏人决定继续跟踪。","sentences":[{"en":"The old book is written in code.","zh":"古书是用密码写成的。","note":"in code：用密码。","id":"u1-story-s0"},{"en":"Ben and Lucy ask Mr Williams for help.","zh":"Ben 和 Lucy 向 Mr Williams 求助。","note":"ask ... for help：向……求助。","id":"u1-story-s1"},{"en":"He says the puzzle is difficult and asks to keep the book.","zh":"他说谜题很难，提出把书留下。","note":"keep：保留。","id":"u1-story-s2"},{"en":"The children do not want to give him the book.","zh":"孩子们不想把书交给他。","note":"do not want to：不想……。","id":"u1-story-s3"},{"en":"Later, someone tries to take their book in the dark.","zh":"后来，有人趁黑想抢他们的书。","note":"in the dark：在黑暗中。","id":"u1-story-s4"},{"en":"The children escape and look for a way to read the code.","zh":"孩子们脱身，寻找读懂密码的方法。","note":"a way to：做……的方法。","id":"u1-story-s5"},{"en":"They discover the key to the code in the book.","zh":"他们在书里发现了解码的关键。","note":"key 在这里不是开门钥匙，而是解码关键。","id":"u1-story-s6"},{"en":"Horax cannot read the code, so he plans to follow them.","zh":"Horax 读不懂密码，于是计划跟踪他们。","note":"so 表示结果。","id":"u1-story-s7"}],"questions":[{"prompt":"为什么孩子们一开始需要帮助？","options":["书写得太小，完全看不见。","书里的内容是密码。","书被水泡没了。"],"answer":1,"why":"问题是读不懂 code，而不是看不清字。","kind":"meaning","id":"u1-story-q0"},{"prompt":"结尾发生了什么变化？","options":["孩子们发现解码方法，Horax 决定跟踪他们。","Mr Williams 当场给了完整答案。","孩子们放弃了古书。"],"answer":0,"why":"他们自己发现解码关键；Horax 仍不懂密码。","kind":"meaning","id":"u1-story-q1"}]},"reading":{"title":"Johnny’s story · 爱做梦的 Johnny","pages":[16,17],"kind":"依据课文的教学改写","summary":"Johnny 在课上常常走神，回答问题闹了笑话。但写作比赛给了他发挥想象力的机会，他终于获得认可。","sentences":[{"en":"Johnny often dreams during lessons at Oak Tree School.","zh":"Johnny 在 Oak Tree School 上课时常常做白日梦。","note":"during lessons：上课期间。","id":"u1-reading-s0"},{"en":"In Geography, he imagines flying on a dragon over the Great Wall.","zh":"地理课上，他想象骑龙飞过长城。","note":"imagines：想象。","id":"u1-reading-s1"},{"en":"In Maths, he works on a puzzle in his head.","zh":"数学课上，他在脑子里解一道谜题。","note":"in his head：在脑中。","id":"u1-reading-s2"},{"en":"His answers do not match the teacher’s questions.","zh":"他的回答和老师的问题对不上。","note":"match：与……相符。","id":"u1-reading-s3"},{"en":"The other children laugh, but Miss Burton is not amused.","zh":"其他孩子笑起来，Miss Burton 却没有笑。","note":"对比孩子与老师的反应。","id":"u1-reading-s4"},{"en":"Later, the class enters a story-writing competition.","zh":"后来，全班参加写故事比赛。","note":"competition：比赛。","id":"u1-reading-s5"},{"en":"Johnny brings his dragons, butterflies and music into one wonderful story.","zh":"Johnny 把龙、蝴蝶和音乐编进一个精彩的故事。","note":"bring ... into：把……融入。","id":"u1-reading-s6"},{"en":"His story wins first prize, and everyone celebrates his imagination.","zh":"他的故事得了一等奖，大家为他的想象力喝彩。","note":"first prize：一等奖。","id":"u1-reading-s7"}],"questions":[{"prompt":"Johnny 的特长最后在哪件事上发挥出来？","options":["写一个富有想象力的故事。","背出全部课堂答案。","修理学校的电视。"],"answer":0,"why":"他将想象编进故事，赢得写作比赛。","kind":"meaning","id":"u1-reading-q0"},{"prompt":"故事提醒我们怎样看待同学？","options":["回答错一次就没有任何能力。","只要走神，就一定能得奖。","每个人可能有不同的优势，也要学会在合适的任务中运用。"],"answer":2,"why":"故事肯定不同思考方式；并不是鼓励忽略所有课堂任务。","kind":"meaning","id":"u1-reading-q1"}]},"world":{"title":"Musical instrument families · 乐器家族","pages":[18,19],"kind":"依据课文的教学改写","summary":"按发声和演奏方式认识吹奏、弦乐与打击乐器；用米粒瓶子做沙锤，感受节奏。","sentences":[{"en":"Musical instruments belong to different families.","zh":"乐器分属不同的家族。","note":"belong to：属于。","id":"u1-world-s0"},{"en":"We blow into wind instruments to make a sound.","zh":"我们向吹奏乐器吹气，让它发声。","note":"blow：吹。","id":"u1-world-s1"},{"en":"A flute and a recorder are wind instruments.","zh":"长笛和竖笛是吹奏乐器。","note":"两种乐器名称。","id":"u1-world-s2"},{"en":"Violins and guitars have strings.","zh":"小提琴和吉他有弦。","note":"strings：琴弦。","id":"u1-world-s3"},{"en":"A piano also has strings, but they are hidden inside.","zh":"钢琴也有弦，但弦藏在内部。","note":"also：也；原书在此按弦乐特征介绍钢琴。","id":"u1-world-s4"},{"en":"Percussion instruments help us play a rhythm.","zh":"打击乐器帮助我们演奏节奏。","note":"rhythm：节奏。","id":"u1-world-s5"},{"en":"We can put rice in closed plastic bottles to make maracas.","zh":"我们可以把米放进盖好的塑料瓶，做成沙锤。","note":"maracas：沙锤；瓶盖由成人协助拧紧。","id":"u1-world-s6"},{"en":"Shaking the bottles makes a sound that can follow the music.","zh":"摇动瓶子发出的声音可以跟着音乐打节拍。","note":"shaking：摇动。","id":"u1-world-s7"}],"questions":[{"prompt":"哪件乐器需要吹气演奏？","options":["吉他。","长笛。","鼓。"],"answer":1,"why":"flute 是 wind instrument。","kind":"meaning","id":"u1-world-q0"},{"prompt":"米粒沙锤最适合用来做什么？","options":["量水温。","阅读地图。","为音乐打节拍。"],"answer":2,"why":"沙锤发出节奏性的声音，是打击乐器。","kind":"meaning","id":"u1-world-q1"}]},"create":{"title":"我的学科与班级规则","pages":[20,21],"tasks":["采访两位家人喜欢的学科，记录不同答案。","写两条 have to 规则，并说明规则的用途。","用三句话讲 Johnny 从被笑到获奖的变化。"],"frame":"My favourite subject is ...\nI like ...\nIn our class, we have to ...\nJohnny dreams about ...\nHis story ...","model":"Johnny dreams during lessons. His answers do not match the questions. In a writing competition, he uses his imagination and wins first prize.","success":"能介绍一项爱好、一条规则；能解释 Johnny 获奖的原因，不只重复“他赢了”。","teacher":"依据所列学生用书活动设计的家庭练习；示范与评价标准为新编，非教师用书标准答案。"},"extra":[],"questions":[{"prompt":"Lucy loves ___ about animals.","options":["learn","learning","learns"],"answer":1,"why":"love 后表示动作使用 learning。","kind":"grammar","id":"u1-g0-q0"},{"prompt":"He ___ like doing Maths puzzles.","options":["don’t","isn’t","doesn’t"],"answer":2,"why":"he 是第三人称单数，否定用 doesn’t like。","kind":"grammar","id":"u1-g0-q1"},{"prompt":"She ___ wear school uniform.","options":["have to","has to","has"],"answer":1,"why":"she 后使用 has to + wear。","kind":"grammar","id":"u1-g1-q0"},{"prompt":"We have to ___ a book every week.","options":["reading","reads","read"],"answer":2,"why":"to 后面接动词原形 read。","kind":"grammar","id":"u1-g1-q1"},{"prompt":"为什么孩子们一开始需要帮助？","options":["书写得太小，完全看不见。","书里的内容是密码。","书被水泡没了。"],"answer":1,"why":"问题是读不懂 code，而不是看不清字。","kind":"meaning","id":"u1-story-q0"},{"prompt":"结尾发生了什么变化？","options":["孩子们发现解码方法，Horax 决定跟踪他们。","Mr Williams 当场给了完整答案。","孩子们放弃了古书。"],"answer":0,"why":"他们自己发现解码关键；Horax 仍不懂密码。","kind":"meaning","id":"u1-story-q1"},{"prompt":"Johnny 的特长最后在哪件事上发挥出来？","options":["写一个富有想象力的故事。","背出全部课堂答案。","修理学校的电视。"],"answer":0,"why":"他将想象编进故事，赢得写作比赛。","kind":"meaning","id":"u1-reading-q0"},{"prompt":"故事提醒我们怎样看待同学？","options":["回答错一次就没有任何能力。","只要走神，就一定能得奖。","每个人可能有不同的优势，也要学会在合适的任务中运用。"],"answer":2,"why":"故事肯定不同思考方式；并不是鼓励忽略所有课堂任务。","kind":"meaning","id":"u1-reading-q1"},{"prompt":"哪件乐器需要吹气演奏？","options":["吉他。","长笛。","鼓。"],"answer":1,"why":"flute 是 wind instrument。","kind":"meaning","id":"u1-world-q0"},{"prompt":"米粒沙锤最适合用来做什么？","options":["量水温。","阅读地图。","为音乐打节拍。"],"answer":2,"why":"沙锤发出节奏性的声音，是打击乐器。","kind":"meaning","id":"u1-world-q1"},{"prompt":"哪个字母的名称和 J 一样含 /eɪ/？","options":["K","I","O"],"answer":0,"why":"J /dʒeɪ/ 和 K /keɪ/ 都有 /eɪ/。","kind":"phonics","id":"u1-ph-q0"}]},{"id":2,"title":"The picnic","zh":"一起去野餐","icon":"🧺","goal":"询问有什么食物、提出建议；说明 Buster 获救的经过，并认识食物链。","start":22,"end":33,"teacher":"未提供教师用书；依据学生用书编写","grammarPage":120,"vocab":[{"word":"rolls","zh":"小圆面包","example":"There are two rolls in my bag."},{"word":"lemonade","zh":"柠檬饮料","example":"Would you like some lemonade?"},{"word":"cheese","zh":"奶酪","example":"There is some cheese in the sandwich."},{"word":"apple juice","zh":"苹果汁","example":"I have some apple juice."},{"word":"water","zh":"水","example":"Is there any water in the bottle?"},{"word":"soup","zh":"汤","example":"The vegetable soup is warm."},{"word":"vegetables","zh":"蔬菜","example":"We need some vegetables for dinner."},{"word":"salad","zh":"沙拉","example":"How about some salad?"}],"grammar":[{"title":"some / any：有没有一些","rule":"肯定句常用 some；一般疑问句和否定句常用 any。不可数名词用 Is there；复数名词用 Are there。","examples":[{"en":"There is some cheese.","zh":"有一些奶酪。"},{"en":"Are there any tomatoes?","zh":"有番茄吗？"}],"questions":[{"prompt":"Is there ___ water in the bottle?","options":["many","a","any"],"answer":2,"why":"询问是否有水，用 any；water 在这里不可数。","kind":"grammar","id":"u2-g0-q0"},{"prompt":"___ there any rolls?","options":["Are","Is","Am"],"answer":0,"why":"rolls 是复数，因此用 Are there。","kind":"grammar","id":"u2-g0-q1"}]},{"title":"提出建议：Shall we ...? / How about ...?","rule":"Shall we 后接动词原形；How about 后可接食物等名词。","examples":[{"en":"Shall we make some soup?","zh":"我们做些汤好吗？"},{"en":"How about some tea?","zh":"来点茶怎么样？"}],"questions":[{"prompt":"Shall we ___ some soup?","options":["making","make","makes"],"answer":1,"why":"Shall we 后面接 make 原形。","kind":"grammar","id":"u2-g1-q0"},{"prompt":"哪句是在建议喝点果汁？","options":["How about some juice?","Is this juice empty?","There isn’t any juice."],"answer":0,"why":"How about ...? 用于提出建议。","kind":"grammar","id":"u2-g1-q1"}]}],"phonics":{"title":"短 /ɪ/ 和双元音 /aɪ/","note":"比较 it 和 ice：/ɪ/ 短而集中；/aɪ/ 从一个元音滑向另一个。第 27 页用 iguana、ice cream 等练习。","pairs":[{"a":"sit","b":"site"},{"a":"bit","b":"bite"},{"a":"fin","b":"fine"}],"page":27,"questions":[{"prompt":"哪一个词含 /aɪ/，和 eye 的元音相同？","options":["sit","fish","ice"],"answer":2,"why":"ice 的开头读 /aɪ/；sit、fish 的元音是短 /ɪ/。","kind":"phonics","id":"u2-ph-q0"}]},"song":{"title":"A picnic","page":24,"task":["打开原书歌谣页，圈出本单元已经会读的词。","用页面的电脑语音练读短句；原版歌曲需另备配套音频。","选一个句型换成自己的信息，说给家人听。"]},"story":{"title":"The golden apple · 金苹果","pages":[26,27],"kind":"依据课文的教学改写","summary":"故事中 Buster 被蛇咬伤，孩子们按老人的指引寻找金苹果。Horax 抢先去摘，却帮孩子们拿到了苹果，他们还找到了第一个字母 I。","sentences":[{"en":"A snake bites Buster, and he becomes very ill.","zh":"一条蛇咬了 Buster，他病得很重。","note":"这是虚构冒险故事，不是动物急救方法。","id":"u2-story-s0"},{"en":"Ben and Lucy take him to the village for help.","zh":"Ben 和 Lucy 带他去村里求助。","note":"for help：为了寻求帮助。","id":"u2-story-s1"},{"en":"An old man tells them about a golden apple above a waterfall.","zh":"一位老人告诉他们，瀑布上方有一个金苹果。","note":"above：在上方。","id":"u2-story-s2"},{"en":"In the story, Buster needs to eat that special apple.","zh":"在故事里，Buster 需要吃那个特殊的苹果。","note":"明确这是故事里的魔法设定。","id":"u2-story-s3"},{"en":"Horax and Zelda try to reach the apple first.","zh":"Horax 和 Zelda 想抢先拿到苹果。","note":"first：首先。","id":"u2-story-s4"},{"en":"Horax loses the apple, and Ben gets it.","zh":"Horax 没有拿住苹果，Ben 得到了它。","note":"转折使问题得到解决。","id":"u2-story-s5"},{"en":"The friends help Buster and discover the letter I by the pool.","zh":"朋友们帮助 Buster，并在水潭边发现字母 I。","note":"letter I：字母 I，不是单词 I 的句意。","id":"u2-story-s6"},{"en":"They write the first letter in their book and continue their adventure.","zh":"他们把第一个字母记在书里，继续冒险。","note":"continue：继续。","id":"u2-story-s7"}],"questions":[{"prompt":"孩子们去找金苹果的直接原因是什么？","options":["要卖苹果换钱。","故事中的 Buster 需要它才能好起来。","要完成美术作业。"],"answer":1,"why":"老人告诉他们，这个故事中的特殊苹果能帮助 Buster。","kind":"meaning","id":"u2-story-q0"},{"prompt":"本次找到的第一个字母是什么？","options":["I。","F。","R。"],"answer":0,"why":"结尾 Lucy 说找到的是 I，并把它记在书里。","kind":"meaning","id":"u2-story-q1"}]},"reading":{"title":"Breakfast in four homes · 四个家庭的早餐","pages":[29],"kind":"依据课文的教学改写","summary":"教材用四个孩子的家庭早餐展示饮食差异。说的是这些家庭的习惯，不代表一个国家里每个人都这样吃。","sentences":[{"en":"Four children describe breakfast in their homes.","zh":"四个孩子介绍自己家里的早餐。","note":"describe：描述。","id":"u2-reading-s0"},{"en":"Ana in Brazil has bread, cheese, cake and fruit.","zh":"巴西的 Ana 吃面包、奶酪、蛋糕和水果。","note":"介绍的是 Ana 的家庭。","id":"u2-reading-s1"},{"en":"She likes mango and watermelon.","zh":"她喜欢芒果和西瓜。","note":"mango：芒果。","id":"u2-reading-s2"},{"en":"Amy describes a special cooked breakfast with foods such as eggs and toast.","zh":"Amy 介绍一顿特别的熟食早餐，包括鸡蛋和吐司等。","note":"such as：例如；不把“特别的一餐”误说成每天都吃。","id":"u2-reading-s3"},{"en":"Rodolfo in northern Mexico has sausage and scrambled eggs with tortillas.","zh":"墨西哥北部的 Rodolfo 吃香肠炒蛋配薄饼。","note":"scrambled eggs：炒蛋；tortillas：墨西哥薄饼。","id":"u2-reading-s4"},{"en":"Mustafa’s family in Turkey puts bread, cheese, eggs and other foods on the table.","zh":"土耳其 Mustafa 家的桌上有面包、奶酪、鸡蛋等食物。","note":"other foods：其他食物。","id":"u2-reading-s5"},{"en":"His family drinks black tea with breakfast.","zh":"他家早餐喝红茶。","note":"black tea 在这里指红茶。","id":"u2-reading-s6"},{"en":"Different families enjoy different breakfasts.","zh":"不同家庭喜欢不同的早餐。","note":"避免把个人例子当作所有人的固定习惯。","id":"u2-reading-s7"}],"questions":[{"prompt":"谁介绍了香肠炒蛋配薄饼？","options":["Ana。","Mustafa。","Rodolfo。"],"answer":2,"why":"Rodolfo 的早餐是 sausage with scrambled eggs，配 tortillas。","kind":"meaning","id":"u2-reading-q0"},{"prompt":"读这些介绍时，哪种理解最合适？","options":["这是四个家庭的例子。","同一国家所有人都吃完全相同的早餐。","四个孩子都不吃鸡蛋。"],"answer":0,"why":"人物介绍的是各自家中的食物，不能概括为全国每个人。","kind":"meaning","id":"u2-reading-q1"}]},"world":{"title":"Food chains and habitats · 食物链与栖息地","pages":[30,31],"kind":"依据课文的教学改写","summary":"认识“谁吃什么”和栖息地。用草—兔子—狐狸这条简单食物链说清能量的传递。","sentences":[{"en":"We get energy from the food we eat.","zh":"我们从吃的食物中获得能量。","note":"energy：能量。","id":"u2-world-s0"},{"en":"Animals need food for energy too.","zh":"动物也需要食物提供能量。","note":"too：也。","id":"u2-world-s1"},{"en":"A food chain shows how living things get food.","zh":"食物链展示生物怎样获得食物。","note":"food chain：食物链。","id":"u2-world-s2"},{"en":"In this example, grass uses sunlight to grow.","zh":"在这个例子里，草利用阳光生长。","note":"in this example：限定为本课的简单例子。","id":"u2-world-s3"},{"en":"A rabbit eats the grass, and a fox eats the rabbit.","zh":"兔子吃草，狐狸吃兔子。","note":"用两个 eats 连起关系。","id":"u2-world-s4"},{"en":"A habitat is the place where an animal lives.","zh":"栖息地就是动物生活的地方。","note":"where 引出“生活的地方”。","id":"u2-world-s5"},{"en":"A rainforest and a pond are different habitats.","zh":"雨林和池塘是不同的栖息地。","note":"pond：池塘。","id":"u2-world-s6"},{"en":"Plants and animals in a habitat are connected through food.","zh":"同一栖息地里的植物和动物通过食物联系起来。","note":"connected：相互联系。","id":"u2-world-s7"}],"questions":[{"prompt":"在草—兔子—狐狸这个例子中，谁吃草？","options":["狐狸。","兔子。","太阳。"],"answer":1,"why":"兔子从草获得食物，狐狸吃兔子。","kind":"meaning","id":"u2-world-q0"},{"prompt":"habitat 的意思是什么？","options":["动物生活的地方。","餐厅的菜单。","某种专用餐具。"],"answer":0,"why":"栖息地指动物居住和生存的环境。","kind":"meaning","id":"u2-world-q1"}]},"create":{"title":"野餐点餐与食物链卡片","pages":[31,32,33],"tasks":["从本单元选择三种野餐食物，问两句 Is/Are there any ...?。","用 Shall we 或 How about 提出一个建议。","画草、兔子、狐狸，按顺序说明谁吃什么。"],"frame":"Is there any ...?\nAre there any ...?\nShall we ...?\nThe rabbit eats ...\nThe fox eats ...","model":"Shall we have a picnic? There are some rolls, but there isn’t any juice. How about some water? A rabbit eats grass, and a fox eats the rabbit.","success":"能区分单数／不可数与复数问法；能讲清食物链的两条进食关系。","teacher":"依据所列学生用书活动设计的家庭练习；示范与评价标准为新编，非教师用书标准答案。"},"extra":[],"questions":[{"prompt":"Is there ___ water in the bottle?","options":["many","a","any"],"answer":2,"why":"询问是否有水，用 any；water 在这里不可数。","kind":"grammar","id":"u2-g0-q0"},{"prompt":"___ there any rolls?","options":["Are","Is","Am"],"answer":0,"why":"rolls 是复数，因此用 Are there。","kind":"grammar","id":"u2-g0-q1"},{"prompt":"Shall we ___ some soup?","options":["making","make","makes"],"answer":1,"why":"Shall we 后面接 make 原形。","kind":"grammar","id":"u2-g1-q0"},{"prompt":"哪句是在建议喝点果汁？","options":["How about some juice?","Is this juice empty?","There isn’t any juice."],"answer":0,"why":"How about ...? 用于提出建议。","kind":"grammar","id":"u2-g1-q1"},{"prompt":"孩子们去找金苹果的直接原因是什么？","options":["要卖苹果换钱。","故事中的 Buster 需要它才能好起来。","要完成美术作业。"],"answer":1,"why":"老人告诉他们，这个故事中的特殊苹果能帮助 Buster。","kind":"meaning","id":"u2-story-q0"},{"prompt":"本次找到的第一个字母是什么？","options":["I。","F。","R。"],"answer":0,"why":"结尾 Lucy 说找到的是 I，并把它记在书里。","kind":"meaning","id":"u2-story-q1"},{"prompt":"谁介绍了香肠炒蛋配薄饼？","options":["Ana。","Mustafa。","Rodolfo。"],"answer":2,"why":"Rodolfo 的早餐是 sausage with scrambled eggs，配 tortillas。","kind":"meaning","id":"u2-reading-q0"},{"prompt":"读这些介绍时，哪种理解最合适？","options":["这是四个家庭的例子。","同一国家所有人都吃完全相同的早餐。","四个孩子都不吃鸡蛋。"],"answer":0,"why":"人物介绍的是各自家中的食物，不能概括为全国每个人。","kind":"meaning","id":"u2-reading-q1"},{"prompt":"在草—兔子—狐狸这个例子中，谁吃草？","options":["狐狸。","兔子。","太阳。"],"answer":1,"why":"兔子从草获得食物，狐狸吃兔子。","kind":"meaning","id":"u2-world-q0"},{"prompt":"habitat 的意思是什么？","options":["动物生活的地方。","餐厅的菜单。","某种专用餐具。"],"answer":0,"why":"栖息地指动物居住和生存的环境。","kind":"meaning","id":"u2-world-q1"},{"prompt":"哪一个词含 /aɪ/，和 eye 的元音相同？","options":["sit","fish","ice"],"answer":2,"why":"ice 的开头读 /aɪ/；sit、fish 的元音是短 /ɪ/。","kind":"phonics","id":"u2-ph-q0"}]},{"id":3,"title":"Daily tasks","zh":"每天的小任务","icon":"🧹","goal":"会说整点、半点和刻钟；说明日常习惯，并从机器人故事理解认真学习与负责。","start":34,"end":45,"teacher":"未提供教师用书；依据学生用书编写","grammarPage":121,"vocab":[{"word":"tidy up","zh":"收拾整齐","example":"I tidy up my room on Saturday."},{"word":"do the shopping","zh":"购物","example":"We do the shopping after lunch."},{"word":"take the dog for a walk","zh":"遛狗","example":"I take the dog for a walk with Dad."},{"word":"wash up","zh":"洗碗","example":"We wash up after dinner."},{"word":"sweep","zh":"扫地","example":"I sweep the kitchen floor."},{"word":"cook","zh":"做饭","example":"My father likes to cook."},{"word":"dry the dishes","zh":"擦干碗碟","example":"I dry the dishes carefully."},{"word":"feed the dog","zh":"喂狗","example":"We feed the dog every morning."}],"grammar":[{"title":"half past / quarter past / quarter to","rule":"half past 是过了半小时，quarter past 是过了一刻钟，quarter to 是差一刻钟到下一个钟点。","examples":[{"en":"It is half past six.","zh":"现在六点半。"},{"en":"It is quarter to seven.","zh":"现在六点四十五分。"}],"questions":[{"prompt":"quarter past five 是几点？","options":["五点十五分。","五点四十五分。","四点四十五分。"],"answer":0,"why":"past 表示过了；quarter 是十五分钟。","kind":"grammar","id":"u3-g0-q0"},{"prompt":"6:45 可以说：","options":["half past six","quarter past six","quarter to seven"],"answer":2,"why":"再过十五分钟到七点，因此是 quarter to seven。","kind":"grammar","id":"u3-g0-q1"}]},{"title":"always / usually / sometimes / never","rule":"这些词说明动作多常发生：总是、通常、有时、从不。这里放在主要动作前。","examples":[{"en":"I always brush my teeth before bed.","zh":"睡前我总是刷牙。"},{"en":"She sometimes washes up.","zh":"她有时洗碗。"}],"questions":[{"prompt":"“我从不在上学前玩电脑游戏”应选：","options":["I always play computer games before school.","I never play computer games before school.","I usually play computer games before school."],"answer":1,"why":"never 表示从不。","kind":"grammar","id":"u3-g1-q0"},{"prompt":"哪句顺序正确？","options":["He sometimes cooks dinner.","He cooks sometimes dinner.","He sometimes dinner cooks."],"answer":0,"why":"本句频率副词 sometimes 放在主要动词 cooks 前。","kind":"grammar","id":"u3-g1-q1"}]}],"phonics":{"title":"/v/ 和 /f/：一个有振动，一个没有","note":"轻咬下唇吹气读 /f/；同样口形加声带振动读 /v/。第 39 页以 van、fans 等练习。","pairs":[{"a":"van","b":"fan"},{"a":"very","b":"fairy"},{"a":"leave","b":"leaf"}],"page":39,"questions":[{"prompt":"哪一个词以 /v/ 开头？","options":["fan","fish","van"],"answer":2,"why":"van 的开头有声带振动，读 /v/。","kind":"phonics","id":"u3-ph-q0"}]},"song":{"title":"What a busy day","page":36,"task":["打开原书歌谣页，圈出本单元已经会读的词。","用页面的电脑语音练读短句；原版歌曲需另备配套音频。","选一个句型换成自己的信息，说给家人听。"]},"story":{"title":"Tidying up · 帮忙才找到线索","pages":[38,39],"kind":"依据课文的教学改写","summary":"坏人为找字母把村里弄乱。Ben 和 Lucy 根据“帮助别人”的提示收拾现场，发现第二个字母 F。","sentences":[{"en":"The next clue says there is a letter in the village.","zh":"下一条线索说，村里藏着一个字母。","note":"clue：线索。","id":"u3-story-s0"},{"en":"Ben is tired and wants to look for it in the morning.","zh":"Ben 累了，想等早晨再找。","note":"in the morning：早晨。","id":"u3-story-s1"},{"en":"Horax and Zelda listen and decide to search after dark.","zh":"Horax 和 Zelda 偷听后，决定天黑再找。","note":"after dark：天黑以后。","id":"u3-story-s2"},{"en":"Their search leaves a terrible mess.","zh":"他们搜寻后留下了一片狼藉。","note":"mess：杂乱。","id":"u3-story-s3"},{"en":"The next morning, Ben and Lucy remember the clue about helping hands.","zh":"第二天早晨，Ben 和 Lucy 想起有关“伸出援手”的线索。","note":"helping hands 在这里指帮助别人。","id":"u3-story-s4"},{"en":"They tidy up the village and move the heavy things.","zh":"他们帮村里收拾，把沉重的东西搬好。","note":"heavy：沉重的。","id":"u3-story-s5"},{"en":"While Lucy clears the rubbish, she finds something important.","zh":"Lucy 清理垃圾时，发现了重要的东西。","note":"rubbish：垃圾。","id":"u3-story-s6"},{"en":"It is F, the second letter in their puzzle.","zh":"那是谜题中的第二个字母 F。","note":"first 是第一；second 是第二。","id":"u3-story-s7"}],"questions":[{"prompt":"为什么村里变得很乱？","options":["Ben 和 Lucy 举办了比赛。","Horax 和 Zelda 搜找字母时弄乱了现场。","村里正在下雪。"],"answer":1,"why":"故事把混乱与坏人夜里找线索联系起来。","kind":"meaning","id":"u3-story-q0"},{"prompt":"哪种行动帮助他们找到 F？","options":["帮助清理村庄。","整天坐着等。","把书扔掉。"],"answer":0,"why":"他们理解 helping hands，收拾时找到字母。","kind":"meaning","id":"u3-story-q1"}]},"reading":{"title":"Arnold and the robot · 没听懂就操作","pages":[40,41],"kind":"依据课文的教学改写","summary":"Arnold 想让机器人代劳，却不会让它停下。科学家回来才控制住机器人。Arnold 决定以后认真听讲。","sentences":[{"en":"William builds robots that help with housework.","zh":"William 制造能帮助做家务的机器人。","note":"housework：家务。","id":"u3-reading-s0"},{"en":"His helper Arnold has to keep the laboratory tidy.","zh":"助手 Arnold 必须保持实验室整洁。","note":"laboratory：实验室。","id":"u3-reading-s1"},{"en":"Arnold does not listen when William teaches him about the robots.","zh":"William 教他机器人知识时，Arnold 没有认真听。","note":"为后面的麻烦埋下原因。","id":"u3-reading-s2"},{"en":"One day, Arnold orders a robot to wash the floor.","zh":"一天，Arnold 命令机器人洗地板。","note":"orders ... to：命令……做……。","id":"u3-reading-s3"},{"en":"The robot keeps filling a bucket and pouring water onto the floor.","zh":"机器人不断装满水桶，把水倒在地板上。","note":"keeps ... -ing：不断做……。","id":"u3-reading-s4"},{"en":"Arnold presses another button, but the robot works even faster.","zh":"Arnold 按另一个按钮，机器人反而动作更快。","note":"even faster：更快了。","id":"u3-reading-s5"},{"en":"William returns and stops the robot, but Arnold must clean up the water.","zh":"William 回来关停机器人，但 Arnold 必须清理积水。","note":"but 连接意外与责任。","id":"u3-reading-s6"},{"en":"Arnold decides to listen carefully next time.","zh":"Arnold 决定下次认真听讲。","note":"listen carefully：仔细听。","id":"u3-reading-s7"}],"questions":[{"prompt":"Arnold 为什么不能及时解决问题？","options":["他以前没认真学习机器人的操作。","机器人没有任何按钮。","William 不会制造机器人。"],"answer":0,"why":"开头说明 Arnold 从不认真听，因此不了解机器人。","kind":"meaning","id":"u3-reading-q0"},{"prompt":"按下第二个按钮后，机器人怎样了？","options":["立刻消失。","开始唱歌。","倒水更快了。"],"answer":2,"why":"故事说机器人 works really fast，水越来越多。","kind":"meaning","id":"u3-reading-q1"}]},"world":{"title":"Saving water · 让每滴水有用","pages":[42,43],"kind":"依据课文的教学改写","summary":"可用的水需要珍惜。用日常习惯练习频率副词，并区分真正用水与浪费水。","sentences":[{"en":"People, animals and plants need water.","zh":"人、动物和植物都需要水。","note":"need：需要。","id":"u3-world-s0"},{"en":"Not all water is clean enough to drink.","zh":"并不是所有水都干净到可以饮用。","note":"not all：并非所有。","id":"u3-world-s1"},{"en":"Some places do not get much rain.","zh":"有些地方降雨不多。","note":"rain 在这里作名词。","id":"u3-world-s2"},{"en":"Wasting water means using it when we do not need to.","zh":"浪费水，就是在不需要的时候仍然用水。","note":"means：意思是。","id":"u3-world-s3"},{"en":"We can turn off the tap while we brush our teeth.","zh":"刷牙时，我们可以关掉水龙头。","note":"turn off：关闭。","id":"u3-world-s4"},{"en":"A bucket can use less water than a running hose when we wash a bike.","zh":"洗自行车时，用水桶可以比一直放水的水管更节约。","note":"less ... than：比……更少。","id":"u3-world-s5"},{"en":"A dripping tap can waste water a little at a time.","zh":"滴水的龙头会一点一点地浪费水。","note":"a little at a time：每次一点点。","id":"u3-world-s6"},{"en":"We can notice our habits and choose one way to save water today.","zh":"我们可以观察自己的习惯，今天就选择一个节水办法。","note":"把知识转成一个具体行动。","id":"u3-world-s7"}],"questions":[{"prompt":"哪种情况属于浪费水？","options":["喝自己需要的水。","不用水时仍让龙头开着。","关好水龙头。"],"answer":1,"why":"定义是：在不需要时仍使用水。","kind":"meaning","id":"u3-world-q0"},{"prompt":"文章建议关注什么？","options":["自己的用水习惯。","只有海洋里的鱼。","一天有多少节课。"],"answer":0,"why":"观察生活习惯能帮助找到节水行动。","kind":"meaning","id":"u3-world-q1"}]},"create":{"title":"我的任务时钟","pages":[44,45],"tasks":["画三个钟面，分别表示整点、半点和刻钟。","在每个钟面旁写一项任务及一个频率词。","用“没听懂—错误操作—承担清理责任”复述 Arnold 的故事。"],"frame":"At ... I ...\nI always ...\nI sometimes ...\nI never ...\nArnold did not ... so ...","model":"I usually do my homework at quarter past five. I sometimes wash up after dinner. Arnold does not understand the robot. It pours too much water, and he has to clean the laboratory.","success":"能说清一个 quarter past 和一个 quarter to；能用故事证据解释 Arnold 的问题。","teacher":"依据所列学生用书活动设计的家庭练习；示范与评价标准为新编，非教师用书标准答案。"},"extra":[],"questions":[{"prompt":"quarter past five 是几点？","options":["五点十五分。","五点四十五分。","四点四十五分。"],"answer":0,"why":"past 表示过了；quarter 是十五分钟。","kind":"grammar","id":"u3-g0-q0"},{"prompt":"6:45 可以说：","options":["half past six","quarter past six","quarter to seven"],"answer":2,"why":"再过十五分钟到七点，因此是 quarter to seven。","kind":"grammar","id":"u3-g0-q1"},{"prompt":"“我从不在上学前玩电脑游戏”应选：","options":["I always play computer games before school.","I never play computer games before school.","I usually play computer games before school."],"answer":1,"why":"never 表示从不。","kind":"grammar","id":"u3-g1-q0"},{"prompt":"哪句顺序正确？","options":["He sometimes cooks dinner.","He cooks sometimes dinner.","He sometimes dinner cooks."],"answer":0,"why":"本句频率副词 sometimes 放在主要动词 cooks 前。","kind":"grammar","id":"u3-g1-q1"},{"prompt":"为什么村里变得很乱？","options":["Ben 和 Lucy 举办了比赛。","Horax 和 Zelda 搜找字母时弄乱了现场。","村里正在下雪。"],"answer":1,"why":"故事把混乱与坏人夜里找线索联系起来。","kind":"meaning","id":"u3-story-q0"},{"prompt":"哪种行动帮助他们找到 F？","options":["帮助清理村庄。","整天坐着等。","把书扔掉。"],"answer":0,"why":"他们理解 helping hands，收拾时找到字母。","kind":"meaning","id":"u3-story-q1"},{"prompt":"Arnold 为什么不能及时解决问题？","options":["他以前没认真学习机器人的操作。","机器人没有任何按钮。","William 不会制造机器人。"],"answer":0,"why":"开头说明 Arnold 从不认真听，因此不了解机器人。","kind":"meaning","id":"u3-reading-q0"},{"prompt":"按下第二个按钮后，机器人怎样了？","options":["立刻消失。","开始唱歌。","倒水更快了。"],"answer":2,"why":"故事说机器人 works really fast，水越来越多。","kind":"meaning","id":"u3-reading-q1"},{"prompt":"哪种情况属于浪费水？","options":["喝自己需要的水。","不用水时仍让龙头开着。","关好水龙头。"],"answer":1,"why":"定义是：在不需要时仍使用水。","kind":"meaning","id":"u3-world-q0"},{"prompt":"文章建议关注什么？","options":["自己的用水习惯。","只有海洋里的鱼。","一天有多少节课。"],"answer":0,"why":"观察生活习惯能帮助找到节水行动。","kind":"meaning","id":"u3-world-q1"},{"prompt":"哪一个词以 /v/ 开头？","options":["fan","fish","van"],"answer":2,"why":"van 的开头有声带振动，读 /v/。","kind":"phonics","id":"u3-ph-q0"}]},{"id":4,"title":"Around town","zh":"城镇探路","icon":"🗺️","goal":"用位置词与目的句指路；理解 Lucy 为什么换一个观察位置，并会辨认四个基本方向。","start":46,"end":57,"teacher":"未提供教师用书；依据学生用书编写","grammarPage":122,"vocab":[{"word":"bank","zh":"银行","example":"The bank is opposite the park."},{"word":"tower","zh":"塔","example":"The old tower is very high."},{"word":"library","zh":"图书馆","example":"I am going to the library to get a book."},{"word":"market square","zh":"集市广场","example":"There are fruit stalls in the market square."},{"word":"supermarket","zh":"超市","example":"We buy vegetables at the supermarket."},{"word":"bus station","zh":"公交车站","example":"The bus station is near the library."},{"word":"sports centre","zh":"体育中心","example":"I play basketball at the sports centre."},{"word":"map","zh":"地图","example":"This map helps us find the tower."}],"grammar":[{"title":"opposite / near / above / below","rule":"opposite 在对面；near 在附近；above 在上方；below 在下方。先找参照物再判断位置。","examples":[{"en":"The bank is opposite the school.","zh":"银行在学校对面。"},{"en":"The clock is above the door.","zh":"钟在门的上方。"}],"questions":[{"prompt":"The lamp is above the table. 哪个在上面？","options":["桌子。","灯。","没有说明。"],"answer":1,"why":"above 前面的 lamp 位于 table 上方。","kind":"grammar","id":"u4-g0-q0"},{"prompt":"学校在公园对面：The school is ___ the park.","options":["opposite","above","below"],"answer":0,"why":"opposite 描述相对的两边。","kind":"grammar","id":"u4-g0-q1"}]},{"title":"去哪里，为了做什么","rule":"be going to + 地点说明去向；后面再用 to + 动词原形说明目的。","examples":[{"en":"I am going to the shop to buy bread.","zh":"我去商店买面包。"},{"en":"She is going to the library to read.","zh":"她去图书馆读书。"}],"questions":[{"prompt":"I am going to the sports centre ___ basketball.","options":["playing","to play","plays"],"answer":1,"why":"to play 表示去体育中心的目的。","kind":"grammar","id":"u4-g1-q0"},{"prompt":"“I am going to the library to get a book.” 中的目的是什么？","options":["去借／拿一本书。","体育中心。","图书馆很高。"],"answer":0,"why":"to get a book 回答“为了做什么”。","kind":"grammar","id":"u4-g1-q1"}]}],"phonics":{"title":"/r/ 与长 /ɑː/","note":"本单元比较 rock 的 /r/ 和 star 中的长元音。英式录音中 car 的词尾 r 常不单独发音；电脑语音口音可能不同。","pairs":[{"a":"red","b":"rock"},{"a":"car","b":"star"},{"a":"park","b":"far"}],"page":51,"questions":[{"prompt":"哪个单词以 /r/ 开头？","options":["car","star","rock"],"answer":2,"why":"rock 的开头是辅音 /r/；car、star 不以它开头。","kind":"phonics","id":"u4-ph-q0"}]},"song":{"title":"Lost in town","page":48,"task":["打开原书歌谣页，圈出本单元已经会读的词。","用页面的电脑语音练读短句；原版歌曲需另备配套音频。","选一个句型换成自己的信息，说给家人听。"]},"story":{"title":"Up high · 换个位置看","pages":[50,51],"kind":"依据课文的教学改写","summary":"线索要求从高处向下看。Lucy 发现游乐场的海盗船比塔更高，换一个观察位置后找到字母 R。","sentences":[{"en":"The clue tells Ben and Lucy to look down from a high place.","zh":"线索让 Ben 和 Lucy 从高处往下看。","note":"look down：向下看。","id":"u4-story-s0"},{"en":"They first head for a tower near the market square.","zh":"他们最初朝集市广场附近的塔走去。","note":"head for：朝……去。","id":"u4-story-s1"},{"en":"Ben notices a funfair and wants to play.","zh":"Ben 看见游乐场，想去玩。","note":"funfair：游乐场、游乐集市。","id":"u4-story-s2"},{"en":"At first, Lucy says there is no time for games.","zh":"起初，Lucy 说没时间玩游戏。","note":"at first：起初。","id":"u4-story-s3"},{"en":"Then she realises that the Pirate Ship goes higher than the tower.","zh":"后来她意识到海盗船能升得比塔更高。","note":"higher than：比……更高。","id":"u4-story-s4"},{"en":"They ride the Pirate Ship and look down at the town.","zh":"他们坐上海盗船，向下看城镇。","note":"ride：乘坐游乐设施。","id":"u4-story-s5"},{"en":"From above, they can see the letter R.","zh":"从高处，他们看到了字母 R。","note":"from above：从上方。","id":"u4-story-s6"},{"en":"Horax and Zelda have gone to the wrong place.","zh":"Horax 和 Zelda 却去了错误的地方。","note":"解决问题有时需要改变观察角度。","id":"u4-story-s7"}],"questions":[{"prompt":"Lucy 为什么改变主意去游乐场？","options":["海盗船提供了更高的观察位置。","她忘了要找字母。","塔已经被拆掉了。"],"answer":0,"why":"她注意到海盗船更高，可以帮助完成线索任务。","kind":"meaning","id":"u4-story-q0"},{"prompt":"这个故事最能说明哪种思考办法？","options":["遇到问题立刻放弃。","一直照原计划做，不看新信息。","根据新信息换一个解决方法。"],"answer":2,"why":"Lucy 结合游乐设施的高度重新选择观察点。","kind":"meaning","id":"u4-story-q1"}]},"reading":{"title":"A useful town map · 地图上的目的地","pages":[52,53],"kind":"依据单元目标新编","summary":"依据教材的城镇地点谜语和目的句新编一段可朗读导览；不代替第 53 页听力答案。","sentences":[{"en":"A town map helps a new visitor find useful places.","zh":"城镇地图帮助新来的游客找到有用的地点。","note":"依据技能页目标新编。","id":"u4-reading-s0"},{"en":"People go to a bank to get money.","zh":"人们去银行取钱。","note":"to get money：表示目的。","id":"u4-reading-s1"},{"en":"They go to a library to find books.","zh":"他们去图书馆找书。","note":"find books：找书。","id":"u4-reading-s2"},{"en":"A market square is a place to buy fruit and vegetables.","zh":"集市广场是买水果和蔬菜的地方。","note":"a place to：可以……的地方。","id":"u4-reading-s3"},{"en":"At a sports centre, people can play games or go swimming.","zh":"在体育中心，人们可以做运动或者游泳。","note":"or：或者。","id":"u4-reading-s4"},{"en":"A visitor can ask, “Where is the library, please?”","zh":"游客可以问：“请问图书馆在哪里？”","note":"please 让问路更礼貌。","id":"u4-reading-s5"},{"en":"A clear answer gives a place and a useful position word.","zh":"清楚的回答会说出地点和有用的位置词。","note":"position word：位置词。","id":"u4-reading-s6"},{"en":"For example, “It is opposite the bank.”","zh":"例如：“它在银行对面。”","note":"这是新编示范位置，并非教材地图答案。","id":"u4-reading-s7"}],"questions":[{"prompt":"如果想找书，文中建议去哪里？","options":["银行。","图书馆。","公交总站。"],"answer":1,"why":"library 是找书的地方。","kind":"meaning","id":"u4-reading-q0"},{"prompt":"哪句回答能帮助游客找到位置？","options":["It is opposite the bank.","I like soup.","It was a sunny day."],"answer":0,"why":"opposite the bank 提供了参照物和方位关系。","kind":"meaning","id":"u4-reading-q1"}]},"world":{"title":"Directions · 东南西北","pages":[54,55],"kind":"依据课文的教学改写","summary":"把地图方向和寻找路线联系起来。先读方向标记，才能可靠地判断地图上的东西南北。","sentences":[{"en":"North, south, east and west are four directions.","zh":"北、南、东、西是四个方向。","note":"direction：方向。","id":"u4-world-s0"},{"en":"On the map in this lesson, north is at the top.","zh":"在本课的地图上，北在上方。","note":"先看具体地图，不能假设所有地图都一样。","id":"u4-world-s1"},{"en":"South is opposite north.","zh":"南与北相对。","note":"opposite：相对。","id":"u4-world-s2"},{"en":"East is on the right of this map, and west is on the left.","zh":"这张地图的东在右边，西在左边。","note":"right / left：右／左。","id":"u4-world-s3"},{"en":"A compass helps explorers find directions.","zh":"指南针帮助探险家辨别方向。","note":"compass：指南针。","id":"u4-world-s4"},{"en":"The marked end of its needle points towards north.","zh":"针上标示北的一端指向北方。","note":"needle：指针。","id":"u4-world-s5"},{"en":"NE means north-east, between north and east.","zh":"NE 表示东北，位于北与东之间。","note":"between：在两者之间。","id":"u4-world-s6"},{"en":"A GPS uses signals from satellites to help people find their position.","zh":"GPS 使用卫星信号帮助人们确定位置。","note":"satellite：卫星；position：位置。","id":"u4-world-s7"}],"questions":[{"prompt":"在本课北向上的地图上，西在哪边？","options":["右边。","下边。","左边。"],"answer":2,"why":"当北向上时，东在右，西在左。","kind":"meaning","id":"u4-world-q0"},{"prompt":"NE 指哪两个方向之间？","options":["北和东。","南和东。","北和西。"],"answer":0,"why":"NE 是 north-east 的缩写。","kind":"meaning","id":"u4-world-q1"}]},"create":{"title":"为小镇设计一条路线","pages":[56,57],"tasks":["画银行、图书馆、体育中心和广场，标出北。","让家人问路，用两个位置词回答。","写两句“去哪里，为了做什么”，再讲 Lucy 的观察办法。"],"frame":"Excuse me. Where is the ...?\nIt is ... the ...\nI am going to the ... to ...\nLucy chooses ... because ...","model":"The library is opposite the bank. I am going to the library to get a book. Lucy chooses the Pirate Ship because it goes higher than the tower.","success":"地图与句子一致；能用 to + 动词说明目的，并解释 Lucy 的选择。","teacher":"依据所列学生用书活动设计的家庭练习；示范与评价标准为新编，非教师用书标准答案。"},"extra":[],"questions":[{"prompt":"The lamp is above the table. 哪个在上面？","options":["桌子。","灯。","没有说明。"],"answer":1,"why":"above 前面的 lamp 位于 table 上方。","kind":"grammar","id":"u4-g0-q0"},{"prompt":"学校在公园对面：The school is ___ the park.","options":["opposite","above","below"],"answer":0,"why":"opposite 描述相对的两边。","kind":"grammar","id":"u4-g0-q1"},{"prompt":"I am going to the sports centre ___ basketball.","options":["playing","to play","plays"],"answer":1,"why":"to play 表示去体育中心的目的。","kind":"grammar","id":"u4-g1-q0"},{"prompt":"“I am going to the library to get a book.” 中的目的是什么？","options":["去借／拿一本书。","体育中心。","图书馆很高。"],"answer":0,"why":"to get a book 回答“为了做什么”。","kind":"grammar","id":"u4-g1-q1"},{"prompt":"Lucy 为什么改变主意去游乐场？","options":["海盗船提供了更高的观察位置。","她忘了要找字母。","塔已经被拆掉了。"],"answer":0,"why":"她注意到海盗船更高，可以帮助完成线索任务。","kind":"meaning","id":"u4-story-q0"},{"prompt":"这个故事最能说明哪种思考办法？","options":["遇到问题立刻放弃。","一直照原计划做，不看新信息。","根据新信息换一个解决方法。"],"answer":2,"why":"Lucy 结合游乐设施的高度重新选择观察点。","kind":"meaning","id":"u4-story-q1"},{"prompt":"如果想找书，文中建议去哪里？","options":["银行。","图书馆。","公交总站。"],"answer":1,"why":"library 是找书的地方。","kind":"meaning","id":"u4-reading-q0"},{"prompt":"哪句回答能帮助游客找到位置？","options":["It is opposite the bank.","I like soup.","It was a sunny day."],"answer":0,"why":"opposite the bank 提供了参照物和方位关系。","kind":"meaning","id":"u4-reading-q1"},{"prompt":"在本课北向上的地图上，西在哪边？","options":["右边。","下边。","左边。"],"answer":2,"why":"当北向上时，东在右，西在左。","kind":"meaning","id":"u4-world-q0"},{"prompt":"NE 指哪两个方向之间？","options":["北和东。","南和东。","北和西。"],"answer":0,"why":"NE 是 north-east 的缩写。","kind":"meaning","id":"u4-world-q1"},{"prompt":"哪个单词以 /r/ 开头？","options":["car","star","rock"],"answer":2,"why":"rock 的开头是辅音 /r/；car、star 不以它开头。","kind":"phonics","id":"u4-ph-q0"}]},{"id":5,"title":"Under the sea","zh":"海底世界","icon":"🐙","goal":"用 was/were 讲过去的位置与状态；复述海底脱困和救助海鹦的故事，发现自然中的图案。","start":58,"end":69,"teacher":"未提供教师用书；依据学生用书编写","grammarPage":123,"vocab":[{"word":"dolphin","zh":"海豚","example":"A dolphin swims near the boat."},{"word":"turtle","zh":"海龟；龟","example":"The turtle has a hard shell."},{"word":"anchor","zh":"锚","example":"The ship has a heavy anchor."},{"word":"octopus","zh":"章鱼","example":"The octopus has eight arms."},{"word":"seahorse","zh":"海马","example":"I can see a small seahorse."},{"word":"seal","zh":"海豹","example":"A seal is resting on the rock."},{"word":"starfish","zh":"海星","example":"The starfish is on the sea floor."},{"word":"shell","zh":"贝壳","example":"There is a shell on the beach."}],"grammar":[{"title":"was / were：过去的状态","rule":"was 和 were 是 be 的过去式。I/he/she/it 用 was；you/we/they 用 were。否定用 wasn’t / weren’t。","examples":[{"en":"The beach was quiet yesterday.","zh":"昨天海滩很安静。"},{"en":"The children were happy.","zh":"孩子们当时很高兴。"}],"questions":[{"prompt":"The dolphins ___ in the sea yesterday.","options":["was","were","is"],"answer":1,"why":"dolphins 是复数，过去状态用 were。","kind":"grammar","id":"u5-g0-q0"},{"prompt":"I ___ at school yesterday. I was at home.","options":["wasn’t","weren’t","isn’t"],"answer":0,"why":"I 的过去否定形式是 wasn’t。","kind":"grammar","id":"u5-g0-q1"}]},{"title":"Was / Were ...?：询问过去","rule":"把 was/were 放在主语前提问；短答保留对应的 was/were，不用 did。","examples":[{"en":"Were you on the beach?","zh":"你当时在海滩上吗？"},{"en":"Yes, I was.","zh":"是的，我在。"}],"questions":[{"prompt":"___ Tim in the sea yesterday?","options":["Were","Did","Was"],"answer":2,"why":"Tim 是一个人，用 Was Tim ...?。","kind":"grammar","id":"u5-g1-q0"},{"prompt":"Were they at the park? 肯定短答是：","options":["Yes, they was.","Yes, they were.","Yes, they did."],"answer":1,"why":"问句用 were，回答也用 were。","kind":"grammar","id":"u5-g1-q1"}]}],"phonics":{"title":"/s/ 与 /ʃ/：s 和 sh","note":"/s/ 像细细的气流，/ʃ/ 像让人安静时的“嘘”。比较 sea/she 和 sip/ship。","pairs":[{"a":"sea","b":"she"},{"a":"sip","b":"ship"},{"a":"sock","b":"shock"}],"page":63,"questions":[{"prompt":"哪个词开头是 /ʃ/？","options":["sea","sock","shell"],"answer":2,"why":"shell 的 sh 读 /ʃ/。","kind":"phonics","id":"u5-ph-q0"}]},"song":{"title":"Fish, fish everywhere","page":60,"task":["打开原书歌谣页，圈出本单元已经会读的词。","用页面的电脑语音练读短句；原版歌曲需另备配套音频。","选一个句型换成自己的信息，说给家人听。"]},"story":{"title":"The trap · 海底陷阱","pages":[62,63],"kind":"依据课文的教学改写","summary":"Ben 的胳膊被大贝壳夹住，坏人又放出鲨鱼。章鱼帮助 Ben 脱困，鱼群组成第四个字母 S。","sentences":[{"en":"Ben and Lucy search under the sea for another letter.","zh":"Ben 和 Lucy 到海底寻找另一个字母。","note":"under the sea：在海底。","id":"u5-story-s0"},{"en":"Ben looks inside a giant shell.","zh":"Ben 查看一个巨大的贝壳里面。","note":"giant：巨大的。","id":"u5-story-s1"},{"en":"His arm gets stuck, and Lucy cannot open the shell.","zh":"他的胳膊被卡住，Lucy 打不开贝壳。","note":"gets stuck：被卡住。","id":"u5-story-s2"},{"en":"Horax and Zelda arrive with a shark in a cage.","zh":"Horax 和 Zelda 带着笼子里的鲨鱼出现。","note":"cage：笼子。","id":"u5-story-s3"},{"en":"They release it, but the angry shark turns towards them.","zh":"他们放出鲨鱼，愤怒的鲨鱼却转向他们。","note":"but 引出意外转折。","id":"u5-story-s4"},{"en":"A helpful octopus opens the shell and frees Ben.","zh":"一只热心的章鱼打开贝壳，让 Ben 脱困。","note":"这是故事中的拟人化情节。","id":"u5-story-s5"},{"en":"The children then notice a group of fish forming a letter.","zh":"接着，孩子们注意到一群鱼组成了一个字母。","note":"forming：形成、组成。","id":"u5-story-s6"},{"en":"The fish make an S, their fourth letter.","zh":"鱼群组成 S，这是他们的第四个字母。","note":"fourth：第四。","id":"u5-story-s7"}],"questions":[{"prompt":"谁帮助 Ben 从贝壳里脱困？","options":["鲨鱼。","章鱼。","Horax。"],"answer":1,"why":"章鱼帮助打开贝壳，Ben 才能把胳膊抽出。","kind":"meaning","id":"u5-story-q0"},{"prompt":"字母 S 是怎样出现的？","options":["刻在一棵树上。","写在医院的门上。","由鱼群组成。"],"answer":2,"why":"结尾 Lucy 让 Ben 看鱼群，它们形成了 S。","kind":"meaning","id":"u5-story-q1"}]},"reading":{"title":"What Christine found · 被发现的小海鹦","pages":[64,65],"kind":"依据课文的教学改写","summary":"风暴过后，Christine 和 Ryan 发现被网困住的小海鹦，照顾它长大。次年再见到海鹦，她相信其中一只是自己帮助过的那只。","sentences":[{"en":"After a storm, Christine and Ryan go to the beach to look for treasures.","zh":"风暴过后，Christine 和 Ryan 去海滩寻宝。","note":"treasures 在这里是贝壳等有趣的发现。","id":"u5-reading-s0"},{"en":"They find a small black-and-white bird caught in a net.","zh":"他们发现一只被网困住的黑白色小鸟。","note":"caught in a net：被网困住。","id":"u5-reading-s1"},{"en":"Christine’s father tells them it is a young puffin.","zh":"Christine 的爸爸告诉他们，那是一只小海鹦。","note":"puffin：海鹦。","id":"u5-reading-s2"},{"en":"He explains that puffins hunt for fish and are good at swimming.","zh":"他解释说，海鹦捕食鱼，擅长游泳。","note":"hunt for：捕猎、寻找食物。","id":"u5-reading-s3"},{"en":"The children make a box with grass and feed the bird fish.","zh":"孩子们在盒子里铺草，给小鸟喂鱼。","note":"这里在复述书中人物的行动。","id":"u5-reading-s4"},{"en":"The puffin grows, and one day it leaves.","zh":"小海鹦长大了，有一天离开了。","note":"grows：长大。","id":"u5-reading-s5"},{"en":"A year later, the children see three puffins on a cliff.","zh":"一年后，孩子们在悬崖上看到三只海鹦。","note":"a year later：一年之后。","id":"u5-reading-s6"},{"en":"Christine feels sure that one is their old friend, although the story does not prove it.","zh":"Christine 相信其中一只是老朋友，不过故事没有证实。","note":"区分人物的确信与已证实的事实。","id":"u5-reading-s7"}],"questions":[{"prompt":"他们最初在哪里发现小海鹦？","options":["一张网里。","学校的课桌上。","市场的笼子里。"],"answer":0,"why":"小鸟被困在海滩的一张网中。","kind":"meaning","id":"u5-reading-q0"},{"prompt":"故事结尾，哪种说法最准确？","options":["他们给海鹦戴了标签，证实它回来了。","Christine 相信一只海鹦是老朋友。","小海鹦亲口告诉了他们名字。"],"answer":1,"why":"原文写她很确信，并没有提供身份确认的证据。","kind":"meaning","id":"u5-reading-q1"}]},"world":{"title":"Patterns and symmetry · 图案与对称","pages":[66,67],"kind":"依据课文的教学改写","summary":"观察动物身上的点和条纹，再用折纸判断两边是否能对应重合，认识对称。","sentences":[{"en":"Animals can have spots, stripes and other patterns.","zh":"动物身上可能有斑点、条纹和其他图案。","note":"pattern：图案。","id":"u5-world-s0"},{"en":"Spots are small marks that look like dots.","zh":"斑点是像小圆点的标记。","note":"spots：斑点。","id":"u5-world-s1"},{"en":"Horizontal stripes go across from side to side.","zh":"水平条纹从一侧横向延伸到另一侧。","note":"horizontal：水平的。","id":"u5-world-s2"},{"en":"Vertical stripes go up and down.","zh":"垂直条纹上下延伸。","note":"vertical：垂直的。","id":"u5-world-s3"},{"en":"A symmetrical shape has two matching sides across a line.","zh":"对称图形在一条线两边有相互对应的部分。","note":"symmetrical：对称的。","id":"u5-world-s4"},{"en":"That line is called a line of symmetry.","zh":"那条线叫作对称轴。","note":"line of symmetry：对称轴。","id":"u5-world-s5"},{"en":"We can fold a paper shape along the line to check the two sides.","zh":"我们可以沿着这条线折叠纸形，检查两边。","note":"fold：折叠。","id":"u5-world-s6"},{"en":"A paper fish is symmetrical when its two halves match.","zh":"当一条纸鱼的两半能对应重合时，它就是对称的。","note":"halves：一半的复数形式。","id":"u5-world-s7"}],"questions":[{"prompt":"horizontal stripes 指什么？","options":["横向条纹。","小圆斑点。","竖向条纹。"],"answer":0,"why":"horizontal 表示水平、横向。","kind":"meaning","id":"u5-world-q0"},{"prompt":"怎样检查画出的纸鱼是否沿中线对称？","options":["只看它是什么颜色。","沿中线折叠，看两半是否重合。","数纸上写了几个字母。"],"answer":1,"why":"对应部分沿对称轴折叠后应能重合。","kind":"meaning","id":"u5-world-q1"}]},"create":{"title":"海洋发现小报告","pages":[67,68,69],"tasks":["画一种海洋动物，标出两处身体特征或图案。","问家人 Were you ... yesterday?，记录一句过去的位置。","用“发现—照顾—离开—再次见到”讲海鹦故事。"],"frame":"My sea animal is ...\nIt has ...\nWere you ... yesterday?\nThe children found ...\nA year later ...","model":"Christine and Ryan find a young puffin in a net. They feed it and it grows. It leaves at the end of summer. A year later, Christine sees puffins and thinks her friend has returned.","success":"能用 was/were 说过去状态；能把人物的猜想说成“她认为”，而不是已证实的事实。","teacher":"依据所列学生用书活动设计的家庭练习；示范与评价标准为新编，非教师用书标准答案。"},"extra":[],"questions":[{"prompt":"The dolphins ___ in the sea yesterday.","options":["was","were","is"],"answer":1,"why":"dolphins 是复数，过去状态用 were。","kind":"grammar","id":"u5-g0-q0"},{"prompt":"I ___ at school yesterday. I was at home.","options":["wasn’t","weren’t","isn’t"],"answer":0,"why":"I 的过去否定形式是 wasn’t。","kind":"grammar","id":"u5-g0-q1"},{"prompt":"___ Tim in the sea yesterday?","options":["Were","Did","Was"],"answer":2,"why":"Tim 是一个人，用 Was Tim ...?。","kind":"grammar","id":"u5-g1-q0"},{"prompt":"Were they at the park? 肯定短答是：","options":["Yes, they was.","Yes, they were.","Yes, they did."],"answer":1,"why":"问句用 were，回答也用 were。","kind":"grammar","id":"u5-g1-q1"},{"prompt":"谁帮助 Ben 从贝壳里脱困？","options":["鲨鱼。","章鱼。","Horax。"],"answer":1,"why":"章鱼帮助打开贝壳，Ben 才能把胳膊抽出。","kind":"meaning","id":"u5-story-q0"},{"prompt":"字母 S 是怎样出现的？","options":["刻在一棵树上。","写在医院的门上。","由鱼群组成。"],"answer":2,"why":"结尾 Lucy 让 Ben 看鱼群，它们形成了 S。","kind":"meaning","id":"u5-story-q1"},{"prompt":"他们最初在哪里发现小海鹦？","options":["一张网里。","学校的课桌上。","市场的笼子里。"],"answer":0,"why":"小鸟被困在海滩的一张网中。","kind":"meaning","id":"u5-reading-q0"},{"prompt":"故事结尾，哪种说法最准确？","options":["他们给海鹦戴了标签，证实它回来了。","Christine 相信一只海鹦是老朋友。","小海鹦亲口告诉了他们名字。"],"answer":1,"why":"原文写她很确信，并没有提供身份确认的证据。","kind":"meaning","id":"u5-reading-q1"},{"prompt":"horizontal stripes 指什么？","options":["横向条纹。","小圆斑点。","竖向条纹。"],"answer":0,"why":"horizontal 表示水平、横向。","kind":"meaning","id":"u5-world-q0"},{"prompt":"怎样检查画出的纸鱼是否沿中线对称？","options":["只看它是什么颜色。","沿中线折叠，看两半是否重合。","数纸上写了几个字母。"],"answer":1,"why":"对应部分沿对称轴折叠后应能重合。","kind":"meaning","id":"u5-world-q1"},{"prompt":"哪个词开头是 /ʃ/？","options":["sea","sock","shell"],"answer":2,"why":"shell 的 sh 读 /ʃ/。","kind":"phonics","id":"u5-ph-q0"}]},{"id":6,"title":"Gadgets","zh":"实用小装置","icon":"🔦","goal":"比较物品、在预算内购物；理解洞穴中的合作解围，并读懂简单数列。","start":70,"end":81,"teacher":"未提供教师用书；依据学生用书编写","grammarPage":124,"vocab":[{"word":"lift","zh":"电梯","example":"We take the lift to the third floor."},{"word":"walkie-talkie","zh":"对讲机","example":"The explorers use a walkie-talkie."},{"word":"torch","zh":"手电筒","example":"The torch helps me see in the dark."},{"word":"CD player","zh":"CD 播放机","example":"This CD player is small."},{"word":"mp3 player","zh":"MP3 播放器","example":"My mp3 player has many songs."},{"word":"mobile phone","zh":"手机","example":"I use a mobile phone to call Mum."},{"word":"electric fan","zh":"电风扇","example":"The electric fan is beside the window."},{"word":"laptop","zh":"笔记本电脑","example":"This laptop is lighter than that one."},{"word":"electric toothbrush","zh":"电动牙刷","example":"My electric toothbrush is blue."},{"word":"games console","zh":"游戏机","example":"The games console is expensive."}],"grammar":[{"title":"比较级：两样东西作比较","rule":"短形容词常加 -er；big 变 bigger。较长形容词常用 more + 形容词；后接 than。","examples":[{"en":"This torch is cheaper than that one.","zh":"这支手电筒比那支便宜。"},{"en":"The blue phone is more expensive.","zh":"蓝色手机更贵。"}],"questions":[{"prompt":"This bag is ___ than my old bag.","options":["bigger","biggest","big"],"answer":0,"why":"有 than，比较两样物品，用 bigger。","kind":"grammar","id":"u6-g0-q0"},{"prompt":"expensive 的比较级是什么？","options":["expensiver","most expensive","more expensive"],"answer":2,"why":"较长形容词 expensive 用 more expensive。","kind":"grammar","id":"u6-g0-q1"}]},{"title":"最高级：在一组中最……","rule":"比较一组事物时，常用 the + -est 或 the most + 形容词，并说明比较范围。","examples":[{"en":"This is the smallest torch in the shop.","zh":"这是商店里最小的手电筒。"},{"en":"It is the most useful thing in my bag.","zh":"它是我包里最有用的东西。"}],"questions":[{"prompt":"这三支手电筒中最便宜的：the ___ torch of the three","options":["cheaper","cheapest","cheap"],"answer":1,"why":"在三个中选最便宜，用最高级 cheapest。","kind":"grammar","id":"u6-g1-q0"},{"prompt":"“书包里最有用的物品”是：","options":["the more useful thing in the bag","most useful than the bag","the most useful thing in the bag"],"answer":2,"why":"最高级 the most useful，并说明范围 in the bag。","kind":"grammar","id":"u6-g1-q1"}]}],"phonics":{"title":"长元音与字母组合","note":"第 75 页练习长元音。这里用 cake、bike、nose 对比短元音；注意有些词尾 e 不发音，却影响前面的元音。","pairs":[{"a":"cap","b":"cape"},{"a":"kit","b":"kite"},{"a":"not","b":"note"}],"page":75,"questions":[{"prompt":"哪一个词的元音和 bike 相同？","options":["big","kite","sit"],"answer":1,"why":"bike 和 kite 的元音都读 /aɪ/。","kind":"phonics","id":"u6-ph-q0"}]},"song":{"title":"My bike is bigger","page":72,"task":["打开原书歌谣页，圈出本单元已经会读的词。","用页面的电脑语音练读短句；原版歌曲需另备配套音频。","选一个句型换成自己的信息，说给家人听。"]},"story":{"title":"The cave · 洞穴里的好主意","pages":[74,75],"kind":"依据课文的教学改写","summary":"Ben 带手电和对讲机下洞找字母。被坏人追进洞后，他靠 Lucy 与 Buster 的机智配合安全离开。","sentences":[{"en":"The next clue sends the friends to some caves.","zh":"下一条线索把朋友们引向洞穴。","note":"cave：洞穴。","id":"u6-story-s0"},{"en":"Ben goes inside with a torch and a walkie-talkie.","zh":"Ben 带着手电筒和对讲机走进去。","note":"with：带着。","id":"u6-story-s1"},{"en":"Lucy stays outside to watch for Horax and Zelda.","zh":"Lucy 留在外面，留意 Horax 和 Zelda。","note":"watch for：注意、提防。","id":"u6-story-s2"},{"en":"Deep in the dark cave, Ben finds beautiful paintings and the letter E.","zh":"在黑暗的洞穴深处，Ben 发现漂亮的壁画和字母 E。","note":"paintings：画；E 是第五个字母。","id":"u6-story-s3"},{"en":"Then the two thieves come into the cave, and Ben hides behind a rock.","zh":"随后两个坏人走进洞里，Ben 藏到岩石后面。","note":"behind：在后面。","id":"u6-story-s4"},{"en":"He tells Lucy about the problem on his walkie-talkie.","zh":"他通过对讲机告诉 Lucy 遇到的麻烦。","note":"on his walkie-talkie：通过对讲机。","id":"u6-story-s5"},{"en":"Lucy uses Buster’s growling sound to frighten the thieves.","zh":"Lucy 利用 Buster 的低吼声吓唬坏人。","note":"growling：低吼。","id":"u6-story-s6"},{"en":"They run away, and Ben gets out safely.","zh":"坏人逃跑了，Ben 平安脱身。","note":"safely：安全地。","id":"u6-story-s7"}],"questions":[{"prompt":"哪些物品帮助 Ben 在洞里看清并联系 Lucy？","options":["电风扇和牙刷。","手电筒和对讲机。","CD 播放机和足球。"],"answer":1,"why":"手电用于照明，对讲机用于保持联系。","kind":"meaning","id":"u6-story-q0"},{"prompt":"坏人为什么逃跑？","options":["他们被 Buster 的吼声吓到了。","他们已经得到所有宝藏。","Ben 告诉他们午餐时间到了。"],"answer":0,"why":"Lucy 让 Buster 的声音吓住他们，帮助 Ben 脱困。","kind":"meaning","id":"u6-story-q1"}]},"reading":{"title":"Choosing a torch · 按预算选手电","pages":[71,76,77],"kind":"依据单元目标新编","summary":"依据教材比较价格、购物问答的目标新编；价格是本练习设置，不是原书听力答案。","sentences":[{"en":"Mia wants a torch for a camping trip.","zh":"Mia 想为露营买一支手电筒。","note":"新编购物情境。","id":"u6-reading-s0"},{"en":"She has twenty pounds to spend.","zh":"她有二十英镑预算。","note":"to spend：可以花费的。","id":"u6-reading-s1"},{"en":"The first torch costs twenty-five pounds.","zh":"第一支手电筒要二十五英镑。","note":"costs：价格是。","id":"u6-reading-s2"},{"en":"It is too expensive for her budget.","zh":"它超出了她的预算。","note":"budget：预算。","id":"u6-reading-s3"},{"en":"She asks, “Have you got a cheaper one?”","zh":"她问：“有便宜一点的吗？”","note":"cheaper：更便宜的。","id":"u6-reading-s4"},{"en":"The assistant shows her a smaller torch for twelve pounds.","zh":"店员给她看一支十二英镑的较小手电。","note":"assistant：店员。","id":"u6-reading-s5"},{"en":"Mia checks that it works and chooses the cheaper torch.","zh":"Mia 检查它能用，然后选了较便宜的那支。","note":"选择依据不只看外观。","id":"u6-reading-s6"},{"en":"She has eight pounds left after paying.","zh":"付款后，她还剩八英镑。","note":"twenty minus twelve is eight。","id":"u6-reading-s7"}],"questions":[{"prompt":"Mia 为什么不选第一支？","options":["它超出二十英镑预算。","它是商店最小的。","她不需要手电。"],"answer":0,"why":"第一支二十五英镑，比她的预算多五英镑。","kind":"meaning","id":"u6-reading-q0"},{"prompt":"买十二英镑的手电后还剩多少钱？","options":["十二英镑。","五英镑。","八英镑。"],"answer":2,"why":"20 − 12 = 8。","kind":"meaning","id":"u6-reading-q1"}]},"world":{"title":"Numbers and sequences · 数字与数列","pages":[78,79],"kind":"依据课文的教学改写","summary":"用罗马数字读数，用相邻两数之和寻找数列规则。聚焦教材中的数学活动，不把历史简述当成完整数学史。","sentences":[{"en":"We use numbers to count, measure and buy things.","zh":"我们用数字计数、测量和购物。","note":"measure：测量。","id":"u6-world-s0"},{"en":"The symbols 0 to 9 are part of the Hindu-Arabic number system.","zh":"0 到 9 这些符号属于印度—阿拉伯数字系统。","note":"number system：记数系统。","id":"u6-world-s1"},{"en":"Roman numerals use letters such as I, V and X.","zh":"罗马数字使用 I、V、X 这样的字母。","note":"Roman numerals：罗马数字。","id":"u6-world-s2"},{"en":"I means one, V means five, and X means ten.","zh":"I 表示一，V 表示五，X 表示十。","note":"记住三个基础符号。","id":"u6-world-s3"},{"en":"VI is six, but IV is four.","zh":"VI 是六，但 IV 是四。","note":"符号的位置会改变运算关系。","id":"u6-world-s4"},{"en":"A number sequence follows a rule.","zh":"数列按照某种规律排列。","note":"sequence：数列。","id":"u6-world-s5"},{"en":"In the sequence 1, 1, 2, 3, 5, each new number is the sum of the two before it.","zh":"数列 1、1、2、3、5 中，每个新数都是前两数之和。","note":"sum：和。","id":"u6-world-s6"},{"en":"The next two numbers in this sequence are eight and thirteen.","zh":"这个数列接下来的两个数是八和十三。","note":"3 + 5 = 8，5 + 8 = 13。","id":"u6-world-s7"}],"questions":[{"prompt":"罗马数字 IV 表示几？","options":["六。","四。","九。"],"answer":1,"why":"小的 I 在 V 前，表示 5 − 1。","kind":"meaning","id":"u6-world-q0"},{"prompt":"1, 1, 2, 3, 5, 8 后面是哪一个数？","options":["9。","11。","13。"],"answer":2,"why":"这个数列把前两数相加，5 + 8 = 13。","kind":"meaning","id":"u6-world-q1"}]},"create":{"title":"预算内购物挑战","pages":[80,81],"tasks":["给三件物品编出价格，总预算为 £30。","写一个比较级和一个最高级，说明选择。","两人扮演顾客与店员，询价、选择并计算余额。"],"frame":"Have you got a ...?\nHow much is it?\nThis ... is cheaper than ...\nIt is the ... in the shop.\nI have ... pounds left.","model":"I have thirty pounds. This torch is twelve pounds, and that one is twenty-five pounds. This one is cheaper. I buy it and have eighteen pounds left.","success":"对话包含询价与选择理由；比较级使用 than；余额计算正确。","teacher":"依据所列学生用书活动设计的家庭练习；示范与评价标准为新编，非教师用书标准答案。"},"extra":[],"questions":[{"prompt":"This bag is ___ than my old bag.","options":["bigger","biggest","big"],"answer":0,"why":"有 than，比较两样物品，用 bigger。","kind":"grammar","id":"u6-g0-q0"},{"prompt":"expensive 的比较级是什么？","options":["expensiver","most expensive","more expensive"],"answer":2,"why":"较长形容词 expensive 用 more expensive。","kind":"grammar","id":"u6-g0-q1"},{"prompt":"这三支手电筒中最便宜的：the ___ torch of the three","options":["cheaper","cheapest","cheap"],"answer":1,"why":"在三个中选最便宜，用最高级 cheapest。","kind":"grammar","id":"u6-g1-q0"},{"prompt":"“书包里最有用的物品”是：","options":["the more useful thing in the bag","most useful than the bag","the most useful thing in the bag"],"answer":2,"why":"最高级 the most useful，并说明范围 in the bag。","kind":"grammar","id":"u6-g1-q1"},{"prompt":"哪些物品帮助 Ben 在洞里看清并联系 Lucy？","options":["电风扇和牙刷。","手电筒和对讲机。","CD 播放机和足球。"],"answer":1,"why":"手电用于照明，对讲机用于保持联系。","kind":"meaning","id":"u6-story-q0"},{"prompt":"坏人为什么逃跑？","options":["他们被 Buster 的吼声吓到了。","他们已经得到所有宝藏。","Ben 告诉他们午餐时间到了。"],"answer":0,"why":"Lucy 让 Buster 的声音吓住他们，帮助 Ben 脱困。","kind":"meaning","id":"u6-story-q1"},{"prompt":"Mia 为什么不选第一支？","options":["它超出二十英镑预算。","它是商店最小的。","她不需要手电。"],"answer":0,"why":"第一支二十五英镑，比她的预算多五英镑。","kind":"meaning","id":"u6-reading-q0"},{"prompt":"买十二英镑的手电后还剩多少钱？","options":["十二英镑。","五英镑。","八英镑。"],"answer":2,"why":"20 − 12 = 8。","kind":"meaning","id":"u6-reading-q1"},{"prompt":"罗马数字 IV 表示几？","options":["六。","四。","九。"],"answer":1,"why":"小的 I 在 V 前，表示 5 − 1。","kind":"meaning","id":"u6-world-q0"},{"prompt":"1, 1, 2, 3, 5, 8 后面是哪一个数？","options":["9。","11。","13。"],"answer":2,"why":"这个数列把前两数相加，5 + 8 = 13。","kind":"meaning","id":"u6-world-q1"},{"prompt":"哪一个词的元音和 bike 相同？","options":["big","kite","sit"],"answer":1,"why":"bike 和 kite 的元音都读 /aɪ/。","kind":"phonics","id":"u6-ph-q0"}]},{"id":7,"title":"In the hospital","zh":"医院里的故事","icon":"🏥","goal":"说出不舒服的部位，用规则与不规则过去式讲事件；理解 Sophia 怎样发现问题并求助。","start":82,"end":93,"teacher":"未提供教师用书；依据学生用书编写","grammarPage":125,"vocab":[{"word":"earache","zh":"耳朵痛","example":"I have an earache."},{"word":"headache","zh":"头痛","example":"He has a headache today."},{"word":"cold","zh":"感冒","example":"I have a cold and feel tired."},{"word":"doctor","zh":"医生","example":"The doctor asks what happened."},{"word":"toothache","zh":"牙痛","example":"She has a toothache."},{"word":"nurse","zh":"护士","example":"The nurse helps the patient."},{"word":"stomach-ache","zh":"肚子痛","example":"Ben has a stomach-ache."},{"word":"cough","zh":"咳嗽","example":"I have a cough."}],"grammar":[{"title":"规则动词过去式：常加 -ed","rule":"讲已经发生的动作，许多动词加 -ed；如 play → played、jump → jumped。","examples":[{"en":"Harry jumped and landed on the floor.","zh":"Harry 跳起来，落到地上。"},{"en":"The doctor looked at his arm.","zh":"医生检查了他的胳膊。"}],"questions":[{"prompt":"Yesterday, we ___ basketball.","options":["play","playing","played"],"answer":2,"why":"yesterday 表示过去，play 的过去式是 played。","kind":"grammar","id":"u7-g0-q0"},{"prompt":"look 的过去式是：","options":["looked","look","looking"],"answer":0,"why":"规则变化在 look 后加 -ed。","kind":"grammar","id":"u7-g0-q1"}]},{"title":"不规则过去式：单独记忆","rule":"一些动词不加 -ed：go → went，feel → felt，have → had，give → gave，say → said，wake up → woke up。","examples":[{"en":"She felt tired and went home.","zh":"她觉得累，就回家了。"},{"en":"He gave me a book.","zh":"他给了我一本书。"}],"questions":[{"prompt":"go 的过去式是：","options":["goed","went","going"],"answer":1,"why":"go 是不规则动词，过去式是 went。","kind":"grammar","id":"u7-g1-q0"},{"prompt":"Yesterday she ___ a stomach-ache.","options":["have","has","had"],"answer":2,"why":"have 的过去式是 had。","kind":"grammar","id":"u7-g1-q1"}]}],"phonics":{"title":"-ed 的读法：不是都多一个音节","note":"liked /t/ 不增加音节；played /d/ 也不增加音节；wanted /ɪd/ 增加音节。第 87 页练读 hiked、liked、skated、hated。","pairs":[{"a":"liked","b":"hiked"},{"a":"played","b":"stayed"},{"a":"wanted","b":"hated"}],"page":87,"questions":[{"prompt":"哪一个词的 -ed 单独增加一个音节？","options":["liked","played","wanted"],"answer":2,"why":"wanted 的 -ed 读 /ɪd/，而 liked /t/、played /d/ 不多一个音节。","kind":"phonics","id":"u7-ph-q0"}]},"song":{"title":"What a week","page":84,"task":["打开原书歌谣页，圈出本单元已经会读的词。","用页面的电脑语音练读短句；原版歌曲需另备配套音频。","选一个句型换成自己的信息，说给家人听。"]},"story":{"title":"At the hospital · 假装生病的坏人","pages":[86,87],"kind":"依据课文的教学改写","summary":"一条假短信把 Ben 和 Lucy 引到医院。病床上其实是 Horax，他索要古书。医生进门给“病人”检查，让孩子们有机会离开。","sentences":[{"en":"Ben receives a message saying his grandfather is in hospital.","zh":"Ben 收到短信，说他的爷爷在医院。","note":"receives：收到；message：消息。","id":"u7-story-s0"},{"en":"He and Lucy go to Room 209.","zh":"他和 Lucy 赶到 209 号病房。","note":"room number：房间号。","id":"u7-story-s1"},{"en":"They enter quietly because they think Grandpa is asleep.","zh":"他们以为爷爷睡着了，于是轻轻走进去。","note":"because 说明原因。","id":"u7-story-s2"},{"en":"But the person in the bed is Horax, not Grandpa.","zh":"可是床上的人是 Horax，并不是爷爷。","note":"辨认真正的人物身份。","id":"u7-story-s3"},{"en":"The message was a trick to bring the children there.","zh":"原来短信是把孩子们骗来的计谋。","note":"trick：骗局。","id":"u7-story-s4"},{"en":"Horax demands the book and the letters.","zh":"Horax 索要古书和字母。","note":"demands：强要。","id":"u7-story-s5"},{"en":"A doctor comes in and asks the children to step outside.","zh":"医生进来，让孩子们先出去。","note":"step outside：到外面去。","id":"u7-story-s6"},{"en":"Ben and Lucy use the chance to leave safely with their information.","zh":"Ben 和 Lucy 抓住机会，带着线索安全离开。","note":"chance：机会。","id":"u7-story-s7"}],"questions":[{"prompt":"为什么 Ben 来到医院？","options":["他收到爷爷生病的短信。","他想买一张地图。","他受邀参加歌唱比赛。"],"answer":0,"why":"短信称 Grandpa 在 209 号病房。","kind":"meaning","id":"u7-story-q0"},{"prompt":"谁实际上在病床上？","options":["Ben 的爷爷。","Horax。","Buster。"],"answer":1,"why":"故事的转折是病床上的“爷爷”其实是 Horax。","kind":"meaning","id":"u7-story-q1"}]},"reading":{"title":"Sophia saves the day · 窗口里的发现","pages":[88,89],"kind":"依据课文的教学改写","summary":"Sophia 踢球伤了膝盖，住院时用望远镜观察窗外。她发现学校附近起火并及时求助，帮助大家避免危险。","sentences":[{"en":"Sophia scores a goal, but she hurts her leg.","zh":"Sophia 踢进一球，却伤了腿。","note":"scores a goal：进球。","id":"u7-reading-s0"},{"en":"The next morning, a doctor checks her knee and arranges an X-ray.","zh":"第二天早晨，医生检查她的膝盖并安排拍 X 光片。","note":"knee：膝盖；X-ray：X 光检查。","id":"u7-reading-s1"},{"en":"Sophia has to stay in hospital for two weeks.","zh":"Sophia 必须住院两周。","note":"has to：不得不。","id":"u7-reading-s2"},{"en":"She feels bored until the doctor gives her binoculars.","zh":"她觉得无聊，直到医生给她一副望远镜。","note":"binoculars：双筒望远镜。","id":"u7-reading-s3"},{"en":"Through them, she can watch the streets and her friends near the school.","zh":"通过望远镜，她能观察街道和学校附近的朋友。","note":"through：通过。","id":"u7-reading-s4"},{"en":"One day, she spots a fire in the wood behind the school.","zh":"一天，她发现学校后面树林里着火了。","note":"spots：发现、看见。","id":"u7-reading-s5"},{"en":"She uses her phone to call the fire brigade.","zh":"她用电话向消防队求助。","note":"fire brigade：消防队。","id":"u7-reading-s6"},{"en":"The news celebrates the girl whose quick call helps save the school.","zh":"新闻表扬了这个及时求助、帮助保护学校的女孩。","note":"用动作与结果解释标题。","id":"u7-reading-s7"}],"questions":[{"prompt":"Sophia 为什么要住院？","options":["她的膝盖受伤，需要治疗。","她想观察轮船。","她要在医院参加比赛。"],"answer":0,"why":"医生在检查与 X 光检查后发现膝盖问题。","kind":"meaning","id":"u7-reading-q0"},{"prompt":"真正帮助保护学校的行动是什么？","options":["只在窗口观看。","发现火情后及时打电话求助。","自己离开医院去扑火。"],"answer":1,"why":"她看见火情并联系消防队；故事没有让她自行灭火。","kind":"meaning","id":"u7-reading-q1"}]},"world":{"title":"Fever words · 读懂身体与体温的词","pages":[90,91],"kind":"依据单元目标新编","summary":"依据本单元科学页练习 fever、temperature、thermometer 等词。这里只学表达与阅读，不把教材简化文字当诊断或用药办法。","sentences":[{"en":"When we feel ill, we may feel hotter than usual.","zh":"生病时，我们有时会觉得比平常热。","note":"may 表示可能，并非每次都一样。","id":"u7-world-s0"},{"en":"The word fever describes an unusually high body temperature.","zh":"fever 描述体温异常升高的情况。","note":"fever：发热。","id":"u7-world-s1"},{"en":"Temperature tells us how hot or cold something is.","zh":"temperature 表示某物有多热或多冷。","note":"temperature：温度。","id":"u7-world-s2"},{"en":"A thermometer is an instrument for measuring temperature.","zh":"thermometer 是测量温度的工具。","note":"thermometer：温度计。","id":"u7-world-s3"},{"en":"The book also uses the words rest, water and germs.","zh":"书中还用了 rest、water 和 germs 这些词。","note":"rest：休息；germs：病菌的日常统称。","id":"u7-world-s4"},{"en":"A patient can tell an adult, “I feel ill and very hot.”","zh":"身体不舒服的人可以告诉大人：“我不舒服，而且很热。”","note":"把感受表达出来。","id":"u7-world-s5"},{"en":"A doctor asks questions to understand what is happening.","zh":"医生通过提问来了解情况。","note":"understand：了解。","id":"u7-world-s6"},{"en":"This reading practises health vocabulary, not decisions about medicine.","zh":"这篇阅读练习健康词汇，不指导用药决定。","note":"理解教材的学习范围。","id":"u7-world-s7"}],"questions":[{"prompt":"哪一个词表示测量温度的工具？","options":["thermometer。","binoculars。","walkie-talkie。"],"answer":0,"why":"thermometer 是温度计；另外两个分别是望远镜和对讲机。","kind":"meaning","id":"u7-world-q0"},{"prompt":"I feel ill and very hot. 表达的是什么？","options":["购物预算。","身体感受。","天气预报的准确温度。"],"answer":1,"why":"句子说“我不舒服，而且感觉很热”，是在描述自己的状态。","kind":"meaning","id":"u7-world-q1"}]},"create":{"title":"一次求助的清楚表达","pages":[92,93],"tasks":["用 I have ... 或 I feel ... 描述一种虚构的身体感受。","用两个过去式说明“发生了什么”，练习向成人清楚求助。","按“受伤—观察—发现—求助”的顺序讲 Sophia 的故事。"],"frame":"I have ...\nI feel ...\nYesterday I ...\nFirst, Sophia ...\nThen she ...\nFinally ...","model":"Sophia hurt her leg and went to hospital. The doctor gave her binoculars. She saw a fire near the school and called the fire brigade. Her quick action helped protect the school.","success":"能区分现在感受与过去事件；复述包含发现危险后求助，不编造治疗或药量。","teacher":"依据所列学生用书活动设计的家庭练习；示范与评价标准为新编，非教师用书标准答案。"},"extra":[],"questions":[{"prompt":"Yesterday, we ___ basketball.","options":["play","playing","played"],"answer":2,"why":"yesterday 表示过去，play 的过去式是 played。","kind":"grammar","id":"u7-g0-q0"},{"prompt":"look 的过去式是：","options":["looked","look","looking"],"answer":0,"why":"规则变化在 look 后加 -ed。","kind":"grammar","id":"u7-g0-q1"},{"prompt":"go 的过去式是：","options":["goed","went","going"],"answer":1,"why":"go 是不规则动词，过去式是 went。","kind":"grammar","id":"u7-g1-q0"},{"prompt":"Yesterday she ___ a stomach-ache.","options":["have","has","had"],"answer":2,"why":"have 的过去式是 had。","kind":"grammar","id":"u7-g1-q1"},{"prompt":"为什么 Ben 来到医院？","options":["他收到爷爷生病的短信。","他想买一张地图。","他受邀参加歌唱比赛。"],"answer":0,"why":"短信称 Grandpa 在 209 号病房。","kind":"meaning","id":"u7-story-q0"},{"prompt":"谁实际上在病床上？","options":["Ben 的爷爷。","Horax。","Buster。"],"answer":1,"why":"故事的转折是病床上的“爷爷”其实是 Horax。","kind":"meaning","id":"u7-story-q1"},{"prompt":"Sophia 为什么要住院？","options":["她的膝盖受伤，需要治疗。","她想观察轮船。","她要在医院参加比赛。"],"answer":0,"why":"医生在检查与 X 光检查后发现膝盖问题。","kind":"meaning","id":"u7-reading-q0"},{"prompt":"真正帮助保护学校的行动是什么？","options":["只在窗口观看。","发现火情后及时打电话求助。","自己离开医院去扑火。"],"answer":1,"why":"她看见火情并联系消防队；故事没有让她自行灭火。","kind":"meaning","id":"u7-reading-q1"},{"prompt":"哪一个词表示测量温度的工具？","options":["thermometer。","binoculars。","walkie-talkie。"],"answer":0,"why":"thermometer 是温度计；另外两个分别是望远镜和对讲机。","kind":"meaning","id":"u7-world-q0"},{"prompt":"I feel ill and very hot. 表达的是什么？","options":["购物预算。","身体感受。","天气预报的准确温度。"],"answer":1,"why":"句子说“我不舒服，而且感觉很热”，是在描述自己的状态。","kind":"meaning","id":"u7-world-q1"},{"prompt":"哪一个词的 -ed 单独增加一个音节？","options":["liked","played","wanted"],"answer":2,"why":"wanted 的 -ed 读 /ɪd/，而 liked /t/、played /d/ 不多一个音节。","kind":"phonics","id":"u7-ph-q0"}]},{"id":8,"title":"Around the world","zh":"环游世界","icon":"🌍","goal":"用过去时说明做过和没做过的事；在模型公园找齐字母，并用折纸了解另一种艺术。","start":94,"end":105,"teacher":"未提供教师用书；依据学生用书编写","grammarPage":126,"vocab":[{"word":"Egypt","zh":"埃及","example":"We read about pyramids in Egypt."},{"word":"Chile","zh":"智利","example":"Chile is in South America."},{"word":"Mexico","zh":"墨西哥","example":"My friend visited Mexico."},{"word":"China","zh":"中国","example":"The Great Wall is in China."},{"word":"Spain","zh":"西班牙","example":"We saw a map of Spain."},{"word":"Argentina","zh":"阿根廷","example":"Argentina is in South America."},{"word":"India","zh":"印度","example":"We found India on the map."},{"word":"Australia","zh":"澳大利亚","example":"The Sydney Opera House is in Australia."},{"word":"Turkey","zh":"土耳其","example":"This flag is the flag of Turkey."},{"word":"Brazil","zh":"巴西","example":"Rio de Janeiro is in Brazil."}],"grammar":[{"title":"过去时否定：didn’t + 动词原形","rule":"didn’t 已经表示过去，后面的动作回到原形：didn’t go，不能说 didn’t went。","examples":[{"en":"We went to the beach, but we didn’t swim.","zh":"我们去了海滩，但没有游泳。"},{"en":"She didn’t buy a postcard.","zh":"她没有买明信片。"}],"questions":[{"prompt":"Yesterday I didn’t ___ to the park.","options":["went","go","going"],"answer":1,"why":"didn’t 后接动词原形 go。","kind":"grammar","id":"u8-g0-q0"},{"prompt":"哪句正确表达“她去了伦敦，但没去动物园”？","options":["She went to London, but she didn’t go to the zoo.","She went to London, but she didn’t went to the zoo.","She go to London, but she doesn’t went to the zoo."],"answer":0,"why":"肯定句使用 went；否定句用 didn’t go。","kind":"grammar","id":"u8-g0-q1"}]},{"title":"Did ...? 询问过去的经历","rule":"Did + 主语 + 动词原形？短答 Yes, ... did. / No, ... didn’t.。特殊疑问词可放在 Did 前。","examples":[{"en":"Did you visit the museum?","zh":"你参观博物馆了吗？"},{"en":"Where did you stay?","zh":"你住在哪里？"}],"questions":[{"prompt":"Did she ___ any photos?","options":["took","takes","take"],"answer":2,"why":"did 后面的动词用原形 take。","kind":"grammar","id":"u8-g1-q0"},{"prompt":"Did they go by train? 否定短答是：","options":["No, they weren’t.","No, they didn’t.","No, they don’t."],"answer":1,"why":"Did 开头的过去时问句用 didn’t 作否定短答。","kind":"grammar","id":"u8-g1-q1"}]}],"phonics":{"title":"/iː/ 和 /ɪ/：长短要分清","note":"第 99 页比较长 /iː/ 与短 /ɪ/。这里用 sheep/ship 等新编词对练习，不依赖字母是否相同。","pairs":[{"a":"sheep","b":"ship"},{"a":"feel","b":"fill"},{"a":"seat","b":"sit"}],"page":99,"questions":[{"prompt":"哪一个词的元音与 sheep 相同？","options":["ship","sit","seat"],"answer":2,"why":"sheep 和 seat 的元音都是长 /iː/。","kind":"phonics","id":"u8-ph-q0"}]},"song":{"title":"All my friends are far away","page":96,"task":["打开原书歌谣页，圈出本单元已经会读的词。","用页面的电脑语音练读短句；原版歌曲需另备配套音频。","选一个句型换成自己的信息，说给家人听。"]},"story":{"title":"The final letters · 模型公园里的字母","pages":[98,99],"kind":"依据课文的教学改写","summary":"孩子们在同一座模型公园看世界建筑。古书不见了，但他们从 INDIA 标牌上发现最后两个字母 N 和 D。","sentences":[{"en":"Ben and Lucy visit a park with models from around the world.","zh":"Ben 和 Lucy 参观一座展示世界模型的公园。","note":"他们没有在一天内飞遍这些国家。","id":"u8-story-s0"},{"en":"They see a football stadium from Brazil and the Great Wall of China.","zh":"他们看到巴西足球场和中国长城的模型。","note":"models：模型。","id":"u8-story-s1"},{"en":"They also visit the Sydney Opera House and the Egyptian pyramids.","zh":"他们还看了悉尼歌剧院和埃及金字塔的模型。","note":"also：也。","id":"u8-story-s2"},{"en":"Mr Williams appears in the park and greets them.","zh":"Mr Williams 在公园出现，向他们打招呼。","note":"appears：出现。","id":"u8-story-s3"},{"en":"The children stop to eat their sandwiches.","zh":"孩子们停下来吃三明治。","note":"stop to eat：停下手头的事去吃东西。","id":"u8-story-s4"},{"en":"Then Lucy discovers that their book is missing.","zh":"接着，Lucy 发现古书不见了。","note":"missing：不见了。","id":"u8-story-s5"},{"en":"Near the Indian model, she notices letters missing from the INDIA sign.","zh":"在印度模型附近，她注意到 INDIA 标牌上缺了字母。","note":"把建筑标牌与寻字母任务联系起来。","id":"u8-story-s6"},{"en":"The missing N and D are the last two letters they need.","zh":"缺少的 N 和 D 正是他们需要的最后两个字母。","note":"之前已有 I、F、R、S、E。","id":"u8-story-s7"}],"questions":[{"prompt":"他们怎样在一天内看到许多国家的建筑？","options":["乘宇宙飞船环游地球。","参观同一座公园里的建筑模型。","真的从巴西游泳到中国。"],"answer":1,"why":"第 94 页引入的是模型村／公园，后续建筑都在这里。","kind":"meaning","id":"u8-story-q0"},{"prompt":"他们找到的最后两个字母是什么？","options":["N 和 D。","A 和 I。","B 和 C。"],"answer":0,"why":"INDIA 标牌缺少 N、D；剩余可见 I、I、A。","kind":"meaning","id":"u8-story-q1"}]},"reading":{"title":"Molly’s London visit · 一封旅行邮件","pages":[95],"kind":"依据课文的教学改写","summary":"Molly 写给 Dana 的邮件按地点、动物和食物介绍旅行。注意“去了哪里”和“没有做什么”的对照。","sentences":[{"en":"Molly writes an email to Dana about London.","zh":"Molly 写邮件给 Dana，介绍伦敦之行。","note":"email：电子邮件。","id":"u8-reading-s0"},{"en":"Yesterday, she went to the zoo with her dad.","zh":"昨天，她和爸爸去了动物园。","note":"went 是 go 的过去式。","id":"u8-reading-s1"},{"en":"Her mum did not go with them; she went shopping.","zh":"妈妈没有一起去，而是去购物了。","note":"did not go：没有去。","id":"u8-reading-s2"},{"en":"They saw elephants, hippos and zebras.","zh":"他们看到了大象、河马和斑马。","note":"saw 是 see 的过去式。","id":"u8-reading-s3"},{"en":"They did not see the lion because it stayed inside its cave.","zh":"他们没看到狮子，因为它待在洞里。","note":"because 说明原因。","id":"u8-reading-s4"},{"en":"After the zoo, they went to a pizza restaurant.","zh":"离开动物园后，他们去了披萨店。","note":"after：在……之后。","id":"u8-reading-s5"},{"en":"Molly did not eat pizza; she chose spaghetti instead.","zh":"Molly 没有吃披萨，而是吃了意大利面。","note":"instead：代替、转而。","id":"u8-reading-s6"},{"en":"She enjoyed the food and wanted to share the visit with her friend.","zh":"她觉得食物好吃，想把这次旅行分享给朋友。","note":"概括邮件的沟通目的。","id":"u8-reading-s7"}],"questions":[{"prompt":"谁和 Molly 一起去了动物园？","options":["她的妈妈。","她的爸爸。","Dana。"],"answer":1,"why":"邮件开头写 Dad and I went to the zoo。","kind":"meaning","id":"u8-reading-q0"},{"prompt":"哪一项与邮件相符？","options":["Molly 吃了披萨并看到了狮子。","Molly 没去动物园。","Molly 吃了意大利面，没有看到狮子。"],"answer":2,"why":"两个否定信息分别是没看到 lion、没吃 pizza。","kind":"meaning","id":"u8-reading-q1"}]},"world":{"title":"Origami · 把纸折成作品","pages":[102,103],"kind":"依据课文的教学改写","summary":"认识 origami 的意思，并按照图示折出模型。把艺术说明读成清楚的动作步骤。","sentences":[{"en":"Origami is the art of folding paper into models.","zh":"Origami 是把纸折成模型的艺术。","note":"folding：折叠。","id":"u8-world-s0"},{"en":"The word comes from Japanese.","zh":"这个词来自日语。","note":"comes from：来自。","id":"u8-world-s1"},{"en":"Ori means fold, and kami means paper.","zh":"ori 表示折叠，kami 表示纸。","note":"帮助记忆单词来源。","id":"u8-world-s2"},{"en":"People can make birds, animals, masks and many other shapes.","zh":"人们可以折出鸟、动物、面具等许多形状。","note":"shapes：形状。","id":"u8-world-s3"},{"en":"For a simple butterfly, the book starts with a square piece of paper.","zh":"做简单蝴蝶时，书中先准备一张正方形纸。","note":"square：正方形。","id":"u8-world-s4"},{"en":"Folding along a diagonal makes a triangle.","zh":"沿对角线折，就得到三角形。","note":"diagonal：对角线。","id":"u8-world-s5"},{"en":"Further folds make the body and wings.","zh":"接着继续折，形成身体和翅膀。","note":"wings：翅膀。","id":"u8-world-s6"},{"en":"We can follow pictures carefully and explain each step to a partner.","zh":"我们可以仔细看图，并向伙伴解释每个步骤。","note":"follow：按照；step：步骤。","id":"u8-world-s7"}],"questions":[{"prompt":"Origami 是哪种艺术？","options":["折纸。","画油画。","雕刻石头。"],"answer":0,"why":"关键意思是 folding paper。","kind":"meaning","id":"u8-world-q0"},{"prompt":"把正方形沿一条对角线对折，会得到什么基本形状？","options":["圆形。","三角形。","五角星。"],"answer":1,"why":"正方形沿对角线折成三角形。","kind":"meaning","id":"u8-world-q1"}]},"create":{"title":"旅行采访与明信片","pages":[104,105],"tasks":["采访一位家人曾去过的地方，也可以明确设定一次虚构旅行。","问一个 Did ...? 问题，记录做过和没做过的事。","写四句明信片，包含地点、同行者、活动与感受。"],"frame":"Where did you go?\nWho did you go with?\nDid you ...?\nI went to ...\nI ... but I didn’t ...\nIt was ...","model":"I went to London with my dad. We visited the zoo, but we didn’t see the lion. After that, we went to a restaurant. I ate spaghetti and had a great day.","success":"问句与否定句在 did/didn’t 后用原形；能说清人物、地点和至少一个对照事实。","teacher":"依据所列学生用书活动设计的家庭练习；示范与评价标准为新编，非教师用书标准答案。"},"extra":[],"questions":[{"prompt":"Yesterday I didn’t ___ to the park.","options":["went","go","going"],"answer":1,"why":"didn’t 后接动词原形 go。","kind":"grammar","id":"u8-g0-q0"},{"prompt":"哪句正确表达“她去了伦敦，但没去动物园”？","options":["She went to London, but she didn’t go to the zoo.","She went to London, but she didn’t went to the zoo.","She go to London, but she doesn’t went to the zoo."],"answer":0,"why":"肯定句使用 went；否定句用 didn’t go。","kind":"grammar","id":"u8-g0-q1"},{"prompt":"Did she ___ any photos?","options":["took","takes","take"],"answer":2,"why":"did 后面的动词用原形 take。","kind":"grammar","id":"u8-g1-q0"},{"prompt":"Did they go by train? 否定短答是：","options":["No, they weren’t.","No, they didn’t.","No, they don’t."],"answer":1,"why":"Did 开头的过去时问句用 didn’t 作否定短答。","kind":"grammar","id":"u8-g1-q1"},{"prompt":"他们怎样在一天内看到许多国家的建筑？","options":["乘宇宙飞船环游地球。","参观同一座公园里的建筑模型。","真的从巴西游泳到中国。"],"answer":1,"why":"第 94 页引入的是模型村／公园，后续建筑都在这里。","kind":"meaning","id":"u8-story-q0"},{"prompt":"他们找到的最后两个字母是什么？","options":["N 和 D。","A 和 I。","B 和 C。"],"answer":0,"why":"INDIA 标牌缺少 N、D；剩余可见 I、I、A。","kind":"meaning","id":"u8-story-q1"},{"prompt":"谁和 Molly 一起去了动物园？","options":["她的妈妈。","她的爸爸。","Dana。"],"answer":1,"why":"邮件开头写 Dad and I went to the zoo。","kind":"meaning","id":"u8-reading-q0"},{"prompt":"哪一项与邮件相符？","options":["Molly 吃了披萨并看到了狮子。","Molly 没去动物园。","Molly 吃了意大利面，没有看到狮子。"],"answer":2,"why":"两个否定信息分别是没看到 lion、没吃 pizza。","kind":"meaning","id":"u8-reading-q1"},{"prompt":"Origami 是哪种艺术？","options":["折纸。","画油画。","雕刻石头。"],"answer":0,"why":"关键意思是 folding paper。","kind":"meaning","id":"u8-world-q0"},{"prompt":"把正方形沿一条对角线对折，会得到什么基本形状？","options":["圆形。","三角形。","五角星。"],"answer":1,"why":"正方形沿对角线折成三角形。","kind":"meaning","id":"u8-world-q1"},{"prompt":"哪一个词的元音与 sheep 相同？","options":["ship","sit","seat"],"answer":2,"why":"sheep 和 seat 的元音都是长 /iː/。","kind":"phonics","id":"u8-ph-q0"}]},{"id":9,"title":"Holiday plans","zh":"假期计划与宝藏","icon":"🌦️","goal":"用 going to 讨论计划；讲清 FRIENDS 与 FINDERS 的区别，理解 Sean 怎样改变对假期的看法。","start":106,"end":117,"teacher":"未提供教师用书；依据学生用书编写","grammarPage":127,"vocab":[{"word":"thunderstorm","zh":"雷暴；雷雨","example":"There is a thunderstorm outside."},{"word":"lightning","zh":"闪电","example":"We can see lightning through the window."},{"word":"cloudy","zh":"多云的","example":"It is cloudy this morning."},{"word":"rainy","zh":"下雨的","example":"It is going to be rainy tomorrow."},{"word":"windy","zh":"有风的","example":"It is windy near the sea."},{"word":"umbrella","zh":"雨伞","example":"I take my umbrella on rainy days."},{"word":"raincoat","zh":"雨衣","example":"My raincoat keeps me dry."},{"word":"foggy","zh":"有雾的","example":"It is foggy in the morning."},{"word":"boots","zh":"靴子","example":"I wear boots when it rains."}],"grammar":[{"title":"be going to：未来计划或预测","rule":"am/is/are going to 后接动词原形。说天气时常用 It is going to be + 形容词。否定在 be 后加 not。","examples":[{"en":"I am going to read a book.","zh":"我打算读一本书。"},{"en":"It is going to be rainy.","zh":"将会下雨。"}],"questions":[{"prompt":"She is going to ___ her grandma.","options":["visits","visited","visit"],"answer":2,"why":"going to 后接动词原形 visit。","kind":"grammar","id":"u9-g0-q0"},{"prompt":"It is going to ___ windy tomorrow.","options":["be","is","are"],"answer":0,"why":"说未来的天气，going to 后用 be 原形。","kind":"grammar","id":"u9-g0-q1"}]},{"title":"Are you going to ...? 讨论计划","rule":"把 am/is/are 放到主语前提问。短答沿用 be：Yes, I am. / No, she isn’t.。","examples":[{"en":"Are you going to swim?","zh":"你打算游泳吗？"},{"en":"What are they going to do?","zh":"他们打算做什么？"}],"questions":[{"prompt":"___ he going to play tennis?","options":["Are","Is","Do"],"answer":1,"why":"he 搭配 is，疑问句把 Is 放在开头。","kind":"grammar","id":"u9-g1-q0"},{"prompt":"Are you going to read tonight? 肯定短答是：","options":["Yes, I do.","Yes, I did.","Yes, I am."],"answer":2,"why":"问句以 Are you 开头，回答用 I am。","kind":"grammar","id":"u9-g1-q1"}]}],"phonics":{"title":"/ɜː/：bird、purple 中的音","note":"第 111 页集中练习 /ɜː/。英式 bird、girl、turn 共享这个长元音；部分美式语音会带 r 音色。","pairs":[{"a":"bird","b":"third"},{"a":"girl","b":"shirt"},{"a":"turn","b":"purple"}],"page":111,"questions":[{"prompt":"哪个词的主要元音与 bird 相同？","options":["girl","bed","bad"],"answer":0,"why":"bird 和 girl 在本课英式发音中都有 /ɜː/。","kind":"phonics","id":"u9-ph-q0"}]},"song":{"title":"A super holiday","page":108,"task":["打开原书歌谣页，圈出本单元已经会读的词。","用页面的电脑语音练读短句；原版歌曲需另备配套音频。","选一个句型换成自己的信息，说给家人听。"]},"story":{"title":"The treasure · 朋友才是钥匙","pages":[110,111],"kind":"依据课文的教学改写","summary":"同样七个字母可以组成 FINDERS，也可以组成 FRIENDS。Horax 只想占有宝藏，Lucy 却读懂了真正的答案：朋友。","sentences":[{"en":"Ben and Lucy find Horax and Zelda with the stolen book.","zh":"Ben 和 Lucy 发现 Horax 和 Zelda 拿着被偷的古书。","note":"stolen：被偷走的。","id":"u9-story-s0"},{"en":"The thieves still need the seven letters to finish a message.","zh":"坏人还需要七个字母来补完整条信息。","note":"finish：完成。","id":"u9-story-s1"},{"en":"The children are discovered, and Ben gives the letters in a mixed order.","zh":"孩子们被发现了，Ben 说出打乱顺序的字母。","note":"mixed order：打乱的顺序。","id":"u9-story-s2"},{"en":"They also learn that Mr Williams was Horax in disguise.","zh":"他们还发现，Mr Williams 原来是 Horax 假扮的。","note":"in disguise：乔装打扮。","id":"u9-story-s3"},{"en":"Horax arranges the letters to spell FINDERS, but the entrance does not open for him.","zh":"Horax 把字母拼成 FINDERS，但入口没有为他打开。","note":"finders：发现者；与 friends 用同一组字母。","id":"u9-story-s4"},{"en":"Lucy rearranges them to spell FRIENDS.","zh":"Lucy 重新排列字母，拼出 FRIENDS。","note":"friends：朋友。","id":"u9-story-s5"},{"en":"True friends can enter, and Ben and Lucy reach the beautiful treasure.","zh":"真正的朋友可以进入，Ben 和 Lucy 找到了美丽的宝藏。","note":"说明正确答案与人物关系。","id":"u9-story-s6"},{"en":"They decide to take it to a museum, where it belongs.","zh":"他们决定把宝藏交给博物馆，让它去该去的地方。","note":"与本册开头的探险家使命呼应。","id":"u9-story-s7"}],"questions":[{"prompt":"真正让孩子们进入的单词是什么？","options":["FINDERS。","FRIENDS。","FINGERS。"],"answer":1,"why":"Lucy 说正确词是 friends，不是 finders。","kind":"meaning","id":"u9-story-q0"},{"prompt":"他们决定怎样处理宝藏？","options":["交给博物馆。","藏到 Horax 家。","自己偷偷卖掉。"],"answer":0,"why":"结尾 Lucy 提议把宝藏送到 museum。","kind":"meaning","id":"u9-story-q1"}]},"reading":{"title":"Holidays with Grandma · 改变想法的假期","pages":[112,113],"kind":"依据课文的教学改写","summary":"Sean 起初觉得农场没有电视、没有伙伴，很无聊。奶奶教他骑马，他逐渐热爱照顾动物，最后不舍得离开。","sentences":[{"en":"Sean is unhappy about spending his holiday on Grandma’s farm.","zh":"Sean 不愿意去奶奶的农场度假。","note":"unhappy：不高兴的。","id":"u9-reading-s0"},{"en":"His parents have work in Africa and cannot take him with them.","zh":"父母要去非洲工作，不能带他同行。","note":"cannot take him：不能带上他。","id":"u9-reading-s1"},{"en":"At first, he complains that there is no television and no other children.","zh":"起初，他抱怨那里没有电视，也没有其他孩子。","note":"at first：最初。","id":"u9-reading-s2"},{"en":"One day, Grandma invites him to meet her horse and pony.","zh":"一天，奶奶带他去看马和小马。","note":"pony：小型马。","id":"u9-reading-s3"},{"en":"She teaches him to ride, starting slowly.","zh":"奶奶从慢慢骑开始，教他骑马。","note":"teaches him to：教他做……。","id":"u9-reading-s4"},{"en":"Sean soon loves riding and helps feed and brush the animals.","zh":"Sean 很快喜欢上骑马，还帮忙喂马、刷毛。","note":"feed / brush：喂食／刷毛。","id":"u9-reading-s5"},{"en":"When his parents return a month later, he no longer feels bored.","zh":"一个月后父母回来时，他已经不再觉得无聊。","note":"no longer：不再。","id":"u9-reading-s6"},{"en":"He asks to stay with Grandma until school starts.","zh":"他请求留在奶奶家，直到开学。","note":"until：直到。","id":"u9-reading-s7"}],"questions":[{"prompt":"Sean 的看法为什么改变了？","options":["农场忽然装了很多电视。","他发现自己喜欢骑马和照顾动物。","父母每天都带他去非洲。"],"answer":1,"why":"他从接触马、学习骑马到主动照顾动物，找到了乐趣。","kind":"meaning","id":"u9-reading-q0"},{"prompt":"开头与结尾最大的变化是什么？","options":["他开始不想去，最后不想离开。","他开始喜欢学校，最后讨厌学校。","他一直觉得农场完全一样无聊。"],"answer":0,"why":"对比两处请求，就能看出态度改变。","kind":"meaning","id":"u9-reading-q1"}]},"world":{"title":"Seasons and hemispheres · 两个半球的季节","pages":[114,115],"kind":"依据课文的教学改写","summary":"从赤道和地轴倾斜理解：南北半球季节不同，热带许多地区更常区分雨季与旱季。","sentences":[{"en":"The Equator divides the Earth into the Northern and Southern hemispheres.","zh":"赤道把地球分为北半球和南半球。","note":"hemisphere：半球。","id":"u9-world-s0"},{"en":"Many places have spring, summer, autumn and winter.","zh":"许多地方有春、夏、秋、冬。","note":"many places 不等于所有地方。","id":"u9-world-s1"},{"en":"The two hemispheres have their seasons at different times.","zh":"两个半球在不同时间迎来相应季节。","note":"at different times：在不同时间。","id":"u9-world-s2"},{"en":"December is in winter in Japan, but in summer in New Zealand.","zh":"十二月在日本是冬季，在新西兰却是夏季。","note":"用 but 对比两个半球。","id":"u9-world-s3"},{"en":"The Earth travels around the sun, and its axis is tilted.","zh":"地球围绕太阳运行，地轴是倾斜的。","note":"axis：地轴；tilted：倾斜的。","id":"u9-world-s4"},{"en":"This changes how much sunlight each hemisphere gets during the year.","zh":"这会改变一年中各半球获得的日照情况。","note":"连接原因与季节变化。","id":"u9-world-s5"},{"en":"Many places near the Equator have wet and dry seasons.","zh":"赤道附近的许多地方有雨季和旱季。","note":"wet / dry：湿润的／干燥的。","id":"u9-world-s6"},{"en":"When we plan a holiday, we need to think about the place and the season.","zh":"计划假期时，我们需要考虑目的地和季节。","note":"把地理知识用在计划中。","id":"u9-world-s7"}],"questions":[{"prompt":"日本十二月是冬季，新西兰的十二月是什么季节？","options":["冬季。","春季。","夏季。"],"answer":2,"why":"两国位于不同半球，教材以此比较相反季节。","kind":"meaning","id":"u9-world-q0"},{"prompt":"哪项有助于解释季节变化？","options":["地轴倾斜，加上地球绕太阳运行。","地球每年换一个形状。","所有地方同一天得到完全相同的日照。"],"answer":0,"why":"地轴倾斜使公转中不同半球的日照情况发生变化。","kind":"meaning","id":"u9-world-q1"}]},"create":{"title":"我的假期计划与全册复述","pages":[116,117],"tasks":["选一个地方，写两项 going to 计划和一种可能的天气。","请家人问 Are you going to ...?，用肯定和否定各回答一次。","把 I、F、R、S、E、N、D 写在纸片上，拼成 FRIENDS，再讲故事结局。"],"frame":"I am going to ...\nIt is going to be ...\nAre you going to ...?\nYes, I am. / No, I’m not.\nThe letters make ...\nThe friends ...","model":"I am going to visit my grandma. We are going to feed the horses. In the adventure, Lucy makes the word FRIENDS. Ben and Lucy find the treasure and take it to a museum.","success":"计划句中 be 与主语一致；能解释为什么 FRIENDS 比 FINDERS 更符合故事主题，并说清宝藏去向。","teacher":"依据所列学生用书活动设计的家庭练习；示范与评价标准为新编，非教师用书标准答案。"},"extra":[],"questions":[{"prompt":"She is going to ___ her grandma.","options":["visits","visited","visit"],"answer":2,"why":"going to 后接动词原形 visit。","kind":"grammar","id":"u9-g0-q0"},{"prompt":"It is going to ___ windy tomorrow.","options":["be","is","are"],"answer":0,"why":"说未来的天气，going to 后用 be 原形。","kind":"grammar","id":"u9-g0-q1"},{"prompt":"___ he going to play tennis?","options":["Are","Is","Do"],"answer":1,"why":"he 搭配 is，疑问句把 Is 放在开头。","kind":"grammar","id":"u9-g1-q0"},{"prompt":"Are you going to read tonight? 肯定短答是：","options":["Yes, I do.","Yes, I did.","Yes, I am."],"answer":2,"why":"问句以 Are you 开头，回答用 I am。","kind":"grammar","id":"u9-g1-q1"},{"prompt":"真正让孩子们进入的单词是什么？","options":["FINDERS。","FRIENDS。","FINGERS。"],"answer":1,"why":"Lucy 说正确词是 friends，不是 finders。","kind":"meaning","id":"u9-story-q0"},{"prompt":"他们决定怎样处理宝藏？","options":["交给博物馆。","藏到 Horax 家。","自己偷偷卖掉。"],"answer":0,"why":"结尾 Lucy 提议把宝藏送到 museum。","kind":"meaning","id":"u9-story-q1"},{"prompt":"Sean 的看法为什么改变了？","options":["农场忽然装了很多电视。","他发现自己喜欢骑马和照顾动物。","父母每天都带他去非洲。"],"answer":1,"why":"他从接触马、学习骑马到主动照顾动物，找到了乐趣。","kind":"meaning","id":"u9-reading-q0"},{"prompt":"开头与结尾最大的变化是什么？","options":["他开始不想去，最后不想离开。","他开始喜欢学校，最后讨厌学校。","他一直觉得农场完全一样无聊。"],"answer":0,"why":"对比两处请求，就能看出态度改变。","kind":"meaning","id":"u9-reading-q1"},{"prompt":"日本十二月是冬季，新西兰的十二月是什么季节？","options":["冬季。","春季。","夏季。"],"answer":2,"why":"两国位于不同半球，教材以此比较相反季节。","kind":"meaning","id":"u9-world-q0"},{"prompt":"哪项有助于解释季节变化？","options":["地轴倾斜，加上地球绕太阳运行。","地球每年换一个形状。","所有地方同一天得到完全相同的日照。"],"answer":0,"why":"地轴倾斜使公转中不同半球的日照情况发生变化。","kind":"meaning","id":"u9-world-q1"},{"prompt":"哪个词的主要元音与 bird 相同？","options":["girl","bed","bad"],"answer":0,"why":"bird 和 girl 在本课英式发音中都有 /ɜː/。","kind":"phonics","id":"u9-ph-q0"}]}],"glossary":[{"word":"explorer","zh":"探险家","example":"The explorer follows a clue."},{"word":"treasure","zh":"宝藏","example":"The treasure belongs in a museum."},{"word":"clue","zh":"线索","example":"This clue helps us solve the puzzle."},{"word":"code","zh":"密码","example":"The book is written in code."},{"word":"museum","zh":"博物馆","example":"We visit a museum."},{"word":"waterfall","zh":"瀑布","example":"The waterfall is high."},{"word":"laboratory","zh":"实验室","example":"The scientist works in a laboratory."},{"word":"rubbish","zh":"垃圾","example":"We put the rubbish in the bin."},{"word":"compass","zh":"指南针","example":"A compass helps us find north."},{"word":"puffin","zh":"海鹦","example":"The puffin catches fish."},{"word":"symmetry","zh":"对称","example":"This shape has symmetry."},{"word":"budget","zh":"预算","example":"My budget is twenty pounds."},{"word":"binoculars","zh":"双筒望远镜","example":"She looks through binoculars."},{"word":"pyramid","zh":"金字塔","example":"There is a pyramid model in the park."},{"word":"hemisphere","zh":"半球","example":"Japan is in the Northern hemisphere."}],"shortLabel":"和探险家一起发现答案","storyHint":"跟着探险家发现线索","version":2,"storageKey":"storysprout:super-minds-3-v2","draftMin":15,"audioNote":"电脑语音合成，不是教材 CD 原声；录音回听与朗读打卡不提供自动发音评分。"};
